('g3_2_soc_u2_L19_challenge#8','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',4,'mc','auto','「통신수단의 올바른 이용」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X42','SO3-2-u2-X43']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C19","difficulty":4,"kind":"mc","stem":"「통신수단의 올바른 이용」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"통신수단을 올바르게 쓰지 않으면 건강을 해치고 남에게 피해를 주므로, 통신 예절을 지키며 때와 장소에 맞게 써요","correct":true},{"t":"통신수단은 언제 어디서 어떻게 써도 아무 문제가 없어요","mis":"SO3-2-u2-X42"},{"t":"통신수단을 쓸 때는 지켜야 할 예절이 따로 없어요","mis":"SO3-2-u2-X43"},{"t":"문제가 있으니 통신수단을 모두 버려야 해요","mis":"SO3-2-u2-X42"}],"explanation":["문제가 생겨요.","예절을 지켜요.","때와 장소에 맞게요."]}'::jsonb),
