('g3_2_soc_u2_review_d#21','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C18',3,'error','auto','통신수단의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":21,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"error","stem":"통신수단의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「통신수단이 발달하면서 교환원이라는 직업이 새로 생겼어.」","correct":true,"mis_target":"SO3-2-u2-X41"},{"t":"친구 가 — 「기지국을 설치하는 통신 설비 기술자가 생겼어.」","mis":"SO3-2-u2-X41"},{"t":"친구 다 — 「무선 호출기는 점차 사라지고 있어.」","mis":"SO3-2-u2-X41"}],"explanation":["교환원을 봐요.","사라졌어요.","친구 나가 잘못 말했어요."]}'::jsonb),
('g3_2_soc_u2_review_d#22','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C14',3,'error','auto','단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X28','SO3-2-u2-X42']::text[],false,'{"seq":22,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"error","stem":"단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「세시 풍속은 절기나 계절과 관계없이 아무 때나 즐기는 풍습이야.」","correct":true,"mis_target":"SO3-2-u2-X01"},{"t":"친구 나 — 「교통의 발달로 생활 공간이 넓어졌어.」","mis":"SO3-2-u2-X28"},{"t":"친구 다 — 「통신수단은 몸과 마음의 건강을 위해 올바르게 써야 해.」","mis":"SO3-2-u2-X42"}],"explanation":["세시 풍속을 봐요.","해마다 일정한 때예요.","친구 가가 잘못 말했어요."]}'::jsonb),
('g3_2_soc_u2_review_d#23','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C6',4,'essay','teacher','옛날부터 오늘날까지 전해 내려오는 풍습이나 전통 놀이 하나를 골라 소개하고, 그것을 미래에도 이어 가려면 어떻게 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-2-u2-C6","difficulty":4,"kind":"essay","stem":"옛날부터 오늘날까지 전해 내려오는 풍습이나 전통 놀이 하나를 골라 소개하고, 그것을 미래에도 이어 가려면 어떻게 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 설날에 복주머니를 차는 풍습은 복이 들어오기를 바라는 뜻이 담겨 있어요. 오늘날에도 복주머니를 선물해요. 미래에도 이어 가려면 학교에서 복주머니를 직접 만들어 보고 가족에게 선물하면 좋겠어요.","scoring_points":["풍습이나 놀이를 하나 골랐는가","바르게 소개했는가","이어 갈 방법을 썼는가"]},"explanation":["하나를 골라요.","소개해요.","방법을 써요."]}'::jsonb),
('g3_2_soc_u2_review_d#24','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C14',4,'essay','teacher','교통의 변화로 좋아진 점과 생긴 문제점을 하나씩 쓰고, 문제점을 줄이기 위해 내가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u2-C14","difficulty":4,"kind":"essay","stem":"교통의 변화로 좋아진 점과 생긴 문제점을 하나씩 쓰고, 문제점을 줄이기 위해 내가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 교통이 발달해 먼 곳에 사는 친척 집에도 반나절이면 갈 수 있게 됐어요. 하지만 자동차가 많아져 대기 오염이 생겼어요. 나는 가까운 곳은 걷거나 자전거를 타고, 먼 곳은 대중교통을 이용하겠어요.","scoring_points":["좋아진 점을 썼는가","문제점을 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["좋아진 점이에요.","문제점이에요.","내 일을 써요."]}'::jsonb),
('g3_2_soc_u2_review_d#25','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C20',4,'essay','teacher','「옛날과 오늘날의 생활 모습」 단원에서 새로 알게 된 점이나 느낀 점을 풍습, 교통, 통신 가운데 두 가지 이상과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u2-C20","difficulty":4,"kind":"essay","stem":"「옛날과 오늘날의 생활 모습」 단원에서 새로 알게 된 점이나 느낀 점을 풍습, 교통, 통신 가운데 두 가지 이상과 이어 쓰세요.","answer_guide":{"answer":"예: 옛날부터 이어져 온 풍습에 가족의 건강과 복을 바라는 조상들의 마음이 담겨 있다는 것을 알게 됐어요. 교통이 발달해서 먼 곳도 빠르게 갈 수 있게 된 것이 신기했어요. 앞으로 통신수단을 안전하고 올바르게 쓰는 사람이 되고 싶어요.","scoring_points":["두 가지 이상과 이었는가","알게 된 점이나 느낀 점을 썼는가","옛날과 오늘날의 변화가 드러났는가"]},"explanation":["두 가지를 골라요.","알게 된 점이에요.","느낀 점이에요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K5-1-u1-C1','kor',5,1,'u1',1,'배려하며 대화하기의 뜻 — 배려하며 대화한다는 것은 상대의 처지에서 생각하고 그 마음에 맞게 말과 태도를 고르는 것이다',ARRAY['6국01-03 듣기·말하기']::text[],1),
('K5-1-u1-C2','kor',5,1,'u1',1,'배려하며 대화하면 좋은 점 — 배려하며 대화하면 서로 기분이 상하지 않고 대화를 이어 갈 수 있으며, 배려는 대화에서 이기거나 빨리 끝내는 기술이 아니라 관계를 지키는 태도이다',ARRAY['6국01-03 듣기·말하기']::text[],2),
('K5-1-u1-C3','kor',5,1,'u1',1,'생략된 내용의 뜻 — 생략된 내용은 말에 다 드러나지 않은 부분으로, 우리는 서로 알고 있다고 여기는 부분을 줄여서 말하므로 대화에는 늘 빈 곳이 있다',ARRAY['6국01-01 듣기·말하기']::text[],3),
('K5-1-u1-C4','kor',5,1,'u1',1,'단서의 뜻 — 단서는 어떤 일을 풀 수 있는 실마리이며, 짐작에는 늘 단서라는 근거가 있어야 한다',ARRAY['6국01-01 듣기·말하기']::text[],4),
('K5-1-u1-C5','kor',5,1,'u1',1,'두 가지가 함께 갖추어진 대화 — 상대를 배려하며 대화하기와 생략된 내용을 짐작하며 대화하기가 함께 갖추어질 때 비로소 대화가 오간다',ARRAY['6국01-03 듣기·말하기']::text[],5),
('K5-1-u1-C6','kor',5,1,'u1',2,'집중해서 듣기 — 상대를 바라보고 고개를 끄덕이며 끝까지 듣는 것이 배려이며, 말을 끊고 다른 이야기를 꺼내면 상대는 하던 말을 멈추게 된다',ARRAY['6국01-03 듣기·말하기']::text[],6),
('K5-1-u1-C7','kor',5,1,'u1',2,'이어서 말하도록 되묻기 — 「그래서 어떻게 했어?」처럼 상대가 하던 말을 이어 가도록 되묻는 것도 잘 듣는 태도이며, 잘 듣는 것은 아무 반응 없이 가만히 있는 것이 아니다',ARRAY['6국01-03 듣기·말하기']::text[],7),
('K5-1-u1-C8','kor',5,1,'u1',2,'상대의 기분을 고려하며 말하기 — 상대의 실수나 잘못을 먼저 탓하지 않고 마음을 헤아리며 말하며, 같은 처지였던 내 경험을 꺼내 마음을 나누기도 한다',ARRAY['6국01-03 듣기·말하기']::text[],8),
('K5-1-u1-C9','kor',5,1,'u1',2,'대화 예절 지키기 — 상대가 말을 마칠 때까지 기다려 차례를 지키고, 상대를 낮추거나 놀리는 말 대신 바른 말씨를 쓰는 것이 대화 예절이다',ARRAY['6국01-03 듣기·말하기']::text[],9),
('K5-1-u1-C10','kor',5,1,'u1',2,'표정과 행동도 말이다 — 같은 말이라도 딴 곳을 보며 하면 마음이 전해지지 않고, 말수가 적어도 눈을 맞추고 고개를 끄덕이면 상대는 말이 받아들여졌다고 느끼므로 배려는 말의 양이 아니라 태도에서 드러난다',ARRAY['6국01-03 듣기·말하기']::text[],10),
('K5-1-u1-C11','kor',5,1,'u1',2,'배려에는 정해진 공식이 없다 — 배려하며 대화하는 방법 네 가지는 외울 공식이 아니며, 상황과 상대에 따라 배려하는 방법이 달라지고 내가 찾은 방법도 배려가 될 수 있다',ARRAY['6국01-03 듣기·말하기']::text[],11),
('K5-1-u1-C12','kor',5,1,'u1',2,'형식보다 진심 — 배려하는 말투와 표정을 흉내 내는 것보다 상대의 처지를 실제로 생각해 보는 것이 먼저이며, 같은 말이라도 마음이 없으면 상대는 알아챈다',ARRAY['6국01-03 듣기·말하기']::text[],12),
('K5-1-u1-C13','kor',5,1,'u1',2,'상황에 어울리는 배려의 말 — 속상한 친구에게는 마음을 알아주는 말, 기뻐하는 친구에게는 함께 기뻐하는 말, 부탁을 어렵게 꺼내는 친구에게는 편하게 말하도록 돕는 말처럼 상황마다 필요한 말이 다르다',ARRAY['6국01-03 듣기·말하기']::text[],13),
('K5-1-u1-C14','kor',5,1,'u1',2,'탓하는 말을 마음 받아 주는 말로 — 위로가 필요한 때에 까닭을 따지거나 마음을 가볍게 넘기지 않고, 먼저 마음을 받아 주는 말을 한 뒤 도울 방법을 보태어 바꾸어 말한다',ARRAY['6국01-03 듣기·말하기']::text[],14),
('K5-1-u1-C15','kor',5,1,'u1',4,'준비 → 대화 → 점검 — 주제를 정하여 대화할 때에는 말할 내용을 준비하고, 배려하며 대화한 뒤, 대화를 잘했는지 스스로 점검하는 차례로 이어진다',ARRAY['6국01-03 듣기·말하기']::text[],15),
('K5-1-u1-C16','kor',5,1,'u1',4,'대화 주제 고르기 — 직접 겪은 일이라면 크고 특별하지 않아도, 즐거운 일이 아니어도(슬펐던 일 · 화났던 일) 주제가 되지만, 아직 겪지 않은 일이나 친구가 숨기고 싶어 하는 비밀은 주제로 알맞지 않다',ARRAY['6국01-03 듣기·말하기']::text[],16),
('K5-1-u1-C17','kor',5,1,'u1',4,'말할 내용의 네 항목 — 말할 내용은 언제(그 일이 있었던 때) · 어디에서(그 일이 있었던 곳) · 무슨 일을(실제로 일어난 일) · 생각이나 느낌(그때 든 마음)으로 정리한다',ARRAY['6국01-03 듣기·말하기']::text[],17),
('K5-1-u1-C18','kor',5,1,'u1',4,'생각이나 느낌을 빠뜨리지 않기 — 네 항목 가운데 생각이나 느낌이 빠지면 있었던 일만 늘어놓는 이야기가 되므로 그때 든 마음까지 준비한다',ARRAY['6국01-03 듣기·말하기']::text[],18),
('K5-1-u1-C19','kor',5,1,'u1',4,'주제는 함께 정하기 — 한쪽이 혼자 주제를 정해 버리면 대화가 시작되기 전에 한 사람이 빠지게 되므로, 서로 의논해서 두 사람이 모두 이야기하고 싶은 주제를 함께 정한다',ARRAY['6국01-03 듣기·말하기']::text[],19),
('K5-1-u1-C20','kor',5,1,'u1',4,'반응하는 말 — 상대의 말을 이어받아 더 묻거나(물 주는 걸 잊은 날은 없었어?) 마음을 알아주는 말(그래서 더 마음이 갔겠다)은 듣고 있다는 신호이며, 「그건 별일 아니네」 · 「내 이야기 먼저 할게」는 대화를 끊는다',ARRAY['6국01-03 듣기·말하기']::text[],20),
('K5-1-u1-C21','kor',5,1,'u1',4,'스스로 점검하고 칭찬하기 — 대화가 끝나면 듣기 · 기분 고려 · 예절 · 표정과 행동을 스스로 점검하고, 친구가 잘한 점을 「끝까지 들어 줘서 고마웠어」처럼 무엇이 좋았는지 짚어 칭찬한다',ARRAY['6국01-03 듣기·말하기']::text[],21),
('K5-1-u1-C22','kor',5,1,'u1',6,'짐작의 네 가지 단서 — 생략된 내용은 말에서 단서 확인하기 · 행동이나 표정에서 단서 확인하기 · 자신의 경험이나 배경지식 떠올리기 · 그때의 상황 고려하기로 짐작한다',ARRAY['6국01-01 듣기·말하기']::text[],22),
('K5-1-u1-C23','kor',5,1,'u1',6,'같은 말, 다른 짐작 — 같은 말을 들어도 사람마다 주목한 단서와 떠올린 경험이 달라 다르게 짐작할 수 있으며, 누구의 짐작이 맞았는지보다 무엇을 보고 그렇게 생각했는지가 중요하다',ARRAY['6국01-01 듣기·말하기']::text[],23),
('K5-1-u1-C24','kor',5,1,'u1',6,'짐작의 두 걸음 — 짐작은 실제로 들은 말과 본 행동 같은 드러난 것을 먼저 확인하고, 그것을 내 경험이나 아는 것 · 그때의 상황과 이어 보는 두 걸음이며, 첫 걸음을 건너뛰면 짐작이 아니라 넘겨짚기가 된다',ARRAY['6국01-01 듣기·말하기']::text[],24),
('K5-1-u1-C25','kor',5,1,'u1',6,'근거가 있는 짐작 — 알맞은 짐작은 대화에 나온 말이나 행동에서 근거를 찾을 수 있는 것이며, 대화 어디에도 근거가 없는 내용은 짐작이 아니라 지어낸 생각이다',ARRAY['6국01-01 듣기·말하기']::text[],25),
('K5-1-u1-C26','kor',5,1,'u1',6,'짐작은 단정이 아니다 — 짐작은 아직 맞는지 모르는 생각이므로 「그럴 것이다」를 「그렇다」로 굳히지 않고, 상대에게 물어 확인하거나 친구의 생각과 견주어 보며, 짐작을 잘하면 대화가 부드러워지고 잘못 짐작하면 오해가 생긴다',ARRAY['6국01-01 듣기·말하기']::text[],26),
('K5-1-u1-C27','kor',5,1,'u1',6,'짐작이 필요한 때 — 대부분의 말은 말한 그대로가 전부이며, 말이 갑자기 짧아지거나 말과 표정이 어긋나거나 되물어야 이해될 때 짐작하며 듣고, 아무 말에나 숨은 뜻을 붙이면 그것도 오해가 된다',ARRAY['6국01-01 듣기·말하기']::text[],27),
('K5-1-u1-C28','kor',5,1,'u1',8,'이야기에 남겨 둔 빈 곳 — 글쓴이는 모든 것을 알려 주지 않고 독자가 단서를 모아 채우도록 남겨 두므로, 제목을 보고 떠오른 물음을 담고 이야기 속 단서를 찾으며 읽는다',ARRAY['6국01-01 듣기·말하기']::text[],28),
('K5-1-u1-C29','kor',5,1,'u1',8,'흩어진 단서 모으기 — 이야기 곳곳에 흩어진 물건 · 행동 · 때의 단서를 하나로 모아 생략된 내용을 짐작하며, 짐작과 관계없는 사실은 단서가 되지 않는다',ARRAY['6국01-01 듣기·말하기']::text[],29),
('K5-1-u1-C30','kor',5,1,'u1',8,'인물의 말과 행동에 담긴 생략 — 인물이 「그냥」이라고 말하거나 물건을 슬그머니 감추는 행동에는 말하기 쑥스럽거나 어려운 까닭이 생략되어 있을 수 있으므로, 앞뒤의 다른 단서와 함께 짐작한다',ARRAY['6국01-01 듣기·말하기']::text[],30),
('K5-1-u1-C31','kor',5,1,'u1',8,'이야기 흐름 간추리기 — 이야기는 처음 · 가운데 · 끝의 중요한 일만 차례대로 골라 간추리며, 분위기를 보여 주는 작은 묘사는 간추릴 때 빼도 된다',ARRAY['6국01-01 듣기·말하기']::text[],31),
('K5-1-u1-C32','kor',5,1,'u1',8,'문맥으로 낱말 뜻 짐작하기 — 모르는 낱말을 만나면 사전을 펴기 전에 앞뒤 문장을 다시 읽어 글쓴이가 남긴 단서로 뜻을 짐작한다(흙을 눌렀더니 물기가 배어 나왔다 → 눅눅하다 = 축축한 기운이 있다)',ARRAY['6국01-01 듣기·말하기']::text[],32),
('K5-1-u1-C33','kor',5,1,'u1',11,'고민을 배려하며 듣기 — 친구의 고민은 끝까지 듣고 마음을 먼저 알아주며 자세히 물어 확인하고, 가벼운 일이라고 넘기거나 다른 친구에게 옮기지 않는다',ARRAY['6국01-03 듣기·말하기']::text[],33),
('K5-1-u1-C34','kor',5,1,'u1',11,'고민 글에 적히지 않은 마음 — 고민 글에는 지금의 마음이 다 적혀 있지 않으므로 「그래서 요즘은 그냥 가만히 있습니다」 같은 말을 단서로 마음을 짐작하고, 짐작이 맞는지 물어본다',ARRAY['6국01-01 듣기·말하기']::text[],34),
('K5-1-u1-C35','kor',5,1,'u1',11,'조언을 건네는 요령 — 조언은 먼저 마음을 알아주는 말을 하고, 내가 해 본 방법을 구체적으로 말한 뒤, 「이렇게 해 보면 어떨까?」처럼 고르도록 권하는 말투로 맺어 상대에게 고를 여지를 남긴다',ARRAY['6국01-03 듣기·말하기']::text[],35),
('K5-1-u1-C36','kor',5,1,'u1',11,'고민에 맞는 조언 — 고민마다 가장 어려워하는 부분이 달라 필요한 도움도 다르므로, 고민의 어려운 곳을 짚어 그에 맞는 방법을 건넨다',ARRAY['6국01-03 듣기·말하기']::text[],36),
('K5-1-u1-C37','kor',5,1,'u1',11,'실천 활동은 반에서 함께 정한다 — 배운 것을 실천하는 활동은 고민 상담소 하나로 정해져 있지 않고, 대화 빙고 놀이 · 이야기에서 짐작하기처럼 반에서 함께 정해 할 수 있다',ARRAY['6국01-03 듣기·말하기']::text[],37),
('K5-1-u1-C38','kor',5,1,'u1',11,'배려와 짐작은 서로 돕는다 — 상대를 배려하기 때문에 말과 행동을 눈여겨보게 되고, 눈여겨보기 때문에 생략된 마음을 짐작할 수 있어, 배려와 짐작은 따로 있지 않고 서로를 돕는다',ARRAY['6국01-01 듣기·말하기']::text[],38),
('K5-1-u1-C39','kor',5,1,'u1',11,'소리의 길이로 뜻 가르기 — 우리말에는 글자는 같지만 소리의 길이가 다른 낱말이 있어(말[말] 사람이 타는 동물 · 말[말ː] 생각을 나타내는 소리, 밤[밤] 해가 진 뒤 · 밤[밤ː] 밤나무의 열매) 길이에 따라 뜻이 달라지며, 길게 소리 낼 때에는 [ː] 표시를 한다 (기초 다지기)',ARRAY['기초 다지기(장단)']::text[],39),
('K5-1-u1-C40','kor',5,1,'u1',11,'문장 속 뜻을 보고 장단 정하기 — 문장에서 그 낱말이 어떤 뜻으로 쓰였는지 먼저 보고 짧은소리와 긴소리를 골라 발음한다(눈[눈] 보는 몸의 부분 · 눈[눈ː] 하늘에서 내리는 것, 벌[벌] 잘못에 주는 괴로움 · 벌[벌ː] 꿀을 모으는 곤충) (기초 다지기)',ARRAY['기초 다지기(장단)']::text[],40)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K5-1-u1-X01','kor',5,'u1',ARRAY['K5-1-u1-C1']::text[],'배려를 듣기 좋은 말로 꾸미는 기술로 여겨 상대의 처지를 생각하지 않는다','상대의 처지에서'),
('K5-1-u1-X02','kor',5,'u1',ARRAY['K5-1-u1-C2']::text[],'배려하며 대화하는 까닭을 대화에서 이기거나 빨리 끝내기 위해서라고 여긴다','관계를 지키는 태도'),
('K5-1-u1-X03','kor',5,'u1',ARRAY['K5-1-u1-C3']::text[],'말한 것만이 대화의 전부라고 여겨 다 드러나지 않은 부분이 있는 줄 모른다','말에는 빈 곳이 있어요'),
('K5-1-u1-X04','kor',5,'u1',ARRAY['K5-1-u1-C4']::text[],'단서 없이 느낌이나 바람대로 짐작한다','무엇을 보고?'),
('K5-1-u1-X05','kor',5,'u1',ARRAY['K5-1-u1-C5','K5-1-u1-C38']::text[],'배려하며 대화하기와 짐작하며 대화하기를 서로 관계없는 따로 떨어진 일로 여긴다','서로를 도와요'),
('K5-1-u1-X06','kor',5,'u1',ARRAY['K5-1-u1-C6']::text[],'상대가 말하는 도중에 말을 끊고 내 이야기나 다른 이야기를 꺼낸다','끝까지 들어요'),
('K5-1-u1-X07','kor',5,'u1',ARRAY['K5-1-u1-C7']::text[],'잘 듣는 것을 아무 반응 없이 가만히 있는 것으로만 여겨 이어 묻지 않는다','되묻는 것도 듣기'),
('K5-1-u1-X08','kor',5,'u1',ARRAY['K5-1-u1-C8']::text[],'상대의 실수나 잘못을 먼저 탓하거나 내 자랑을 앞세운다','마음부터 헤아려요'),
('K5-1-u1-X09','kor',5,'u1',ARRAY['K5-1-u1-C9']::text[],'마음만 있으면 차례를 어기거나 놀리는 말을 섞어도 괜찮다고 여긴다','차례 · 바른 말씨'),
('K5-1-u1-X10','kor',5,'u1',ARRAY['K5-1-u1-C10']::text[],'말만 바르면 딴 곳을 보거나 다른 일을 하며 대화해도 마음이 전해진다고 여긴다','표정과 행동도 말'),
('K5-1-u1-X11','kor',5,'u1',ARRAY['K5-1-u1-C10']::text[],'배려는 말을 길게 많이 해 주는 것이라고 여긴다','양이 아니라 태도'),
('K5-1-u1-X12','kor',5,'u1',ARRAY['K5-1-u1-C11']::text[],'배려하는 방법 네 가지를 외워 그대로만 하면 되고 다른 방법은 배려가 아니라고 여긴다','정해진 공식은 없어요'),
('K5-1-u1-X13','kor',5,'u1',ARRAY['K5-1-u1-C12']::text[],'배려하는 말이나 말투만 흉내 내면 마음이 없어도 전해진다고 여긴다','상대는 알아채요'),
('K5-1-u1-X14','kor',5,'u1',ARRAY['K5-1-u1-C13']::text[],'상황과 상관없이 같은 말로 반응해, 기뻐하는 친구를 위로하거나 속상한 친구에게 축하하듯 말한다','지금 무엇을 바라나?'),
('K5-1-u1-X15','kor',5,'u1',ARRAY['K5-1-u1-C14']::text[],'위로가 필요한 때에 까닭을 따지거나 「다음에 잘하면 되잖아」처럼 속상한 마음을 가볍게 넘긴다','마음을 먼저 받아 줘요'),
('K5-1-u1-X16','kor',5,'u1',ARRAY['K5-1-u1-C15']::text[],'준비 없이 대화를 시작하거나 대화가 끝나면 점검하지 않는다','준비 → 대화 → 점검'),
('K5-1-u1-X17','kor',5,'u1',ARRAY['K5-1-u1-C16']::text[],'대화 주제는 크고 특별하거나 즐거운 일이어야만 한다고 여긴다','겪은 일이면 무엇이든'),
('K5-1-u1-X18','kor',5,'u1',ARRAY['K5-1-u1-C16']::text[],'아직 겪지 않은 일이나 친구가 숨기고 싶어 하는 비밀을 대화 주제로 고른다','내가 겪은 일인가?'),
('K5-1-u1-X19','kor',5,'u1',ARRAY['K5-1-u1-C17']::text[],'언제 · 어디에서 · 무슨 일을 · 생각이나 느낌의 네 항목을 헷갈려 엉뚱한 칸에 넣는다','때 · 곳 · 일 · 마음'),
('K5-1-u1-X20','kor',5,'u1',ARRAY['K5-1-u1-C18']::text[],'생각이나 느낌을 빼고 있었던 일만 늘어놓는다','그때 든 마음은?'),
('K5-1-u1-X21','kor',5,'u1',ARRAY['K5-1-u1-C19']::text[],'주제를 한쪽이 혼자 정하거나, 상대가 정한 대로 말없이 따라가기만 한다','함께 의논해요'),
('K5-1-u1-X22','kor',5,'u1',ARRAY['K5-1-u1-C20']::text[],'「그건 별일 아니네」처럼 상대의 말을 가볍게 넘기거나 반응 없이 내 이야기로 넘어간다','이어받아 반응해요'),
('K5-1-u1-X23','kor',5,'u1',ARRAY['K5-1-u1-C21']::text[],'대화를 점검하지 않거나, 친구를 칭찬할 때 무엇이 좋았는지 짚지 않고 「그냥 다 잘했어」로 넘긴다','잘한 점을 짚어요'),
('K5-1-u1-X24','kor',5,'u1',ARRAY['K5-1-u1-C22']::text[],'짐작의 단서를 말에서만 찾고 행동 · 경험 · 상황은 살피지 않는다','네 가지 단서'),
('K5-1-u1-X25','kor',5,'u1',ARRAY['K5-1-u1-C22']::text[],'짐작에 쓴 단서가 말인지 · 행동인지 · 경험인지 · 상황인지 헷갈린다','무엇을 보고 · 들었나?'),
('K5-1-u1-X26','kor',5,'u1',ARRAY['K5-1-u1-C23']::text[],'나와 다르게 짐작한 친구는 틀렸다고 여기거나 누구의 짐작이 맞았는지만 따진다','무엇을 보고 그렇게?'),
('K5-1-u1-X27','kor',5,'u1',ARRAY['K5-1-u1-C24']::text[],'드러난 말과 행동을 확인하지 않고 바로 넘겨짚는다','드러난 것부터'),
('K5-1-u1-X28','kor',5,'u1',ARRAY['K5-1-u1-C25']::text[],'대화 어디에도 근거가 없는 내용까지 알맞게 짐작했다고 여긴다','대화에 근거가 있나?'),
('K5-1-u1-X29','kor',5,'u1',ARRAY['K5-1-u1-C26']::text[],'짐작한 내용을 확인하지 않고 사실처럼 믿거나 다른 사람에게 알린다','짐작은 단정이 아니에요'),
('K5-1-u1-X30','kor',5,'u1',ARRAY['K5-1-u1-C27']::text[],'모든 말에 숨은 뜻이 있다고 여겨 아무 말에나 뜻을 붙인다','대부분은 말 그대로'),
('K5-1-u1-X31','kor',5,'u1',ARRAY['K5-1-u1-C28']::text[],'이야기는 글쓴이가 모든 것을 다 알려 준다고 여겨 빈 곳을 채우며 읽지 않는다','남겨 둔 빈 곳'),
('K5-1-u1-X32','kor',5,'u1',ARRAY['K5-1-u1-C29']::text[],'짐작과 관계없는 사실까지 단서로 삼거나 단서 하나만 보고 판단한다','흩어진 단서를 모아요'),
('K5-1-u1-X33','kor',5,'u1',ARRAY['K5-1-u1-C30']::text[],'인물이 「그냥」이라고 하면 정말 아무 까닭이 없다고 여기거나, 행동에 담긴 마음을 엉뚱하게 짐작한다','말하지 못한 까닭'),
('K5-1-u1-X34','kor',5,'u1',ARRAY['K5-1-u1-C31']::text[],'간추릴 때 중요하지 않은 묘사까지 넣거나 일의 차례를 뒤섞는다','중요한 일만 차례대로'),
('K5-1-u1-X35','kor',5,'u1',ARRAY['K5-1-u1-C32']::text[],'모르는 낱말을 앞뒤 문장을 보지 않고 넘기거나 엉뚱한 뜻으로 짐작한다','앞뒤에 단서가 있어요'),
('K5-1-u1-X36','kor',5,'u1',ARRAY['K5-1-u1-C33']::text[],'친구의 고민을 가벼운 일로 넘기거나 다른 친구에게 옮긴다','끝까지 · 마음 먼저'),
('K5-1-u1-X37','kor',5,'u1',ARRAY['K5-1-u1-C34']::text[],'고민 글에 적힌 말만 읽고 적히지 않은 마음은 살피지 않는다','「그래서 …」가 단서'),
('K5-1-u1-X38','kor',5,'u1',ARRAY['K5-1-u1-C35']::text[],'조언을 「이렇게 해」처럼 시키거나 탓하는 말로 하고, 마음을 알아주는 말을 빠뜨린다','마음 → 방법 → 권하기'),
('K5-1-u1-X39','kor',5,'u1',ARRAY['K5-1-u1-C36']::text[],'고민에서 어려워하는 부분과 맞지 않는 조언을 건넨다','어디가 어려운가?'),
('K5-1-u1-X40','kor',5,'u1',ARRAY['K5-1-u1-C37']::text[],'배운 것을 실천하는 활동은 정해진 한 가지뿐이라고 여긴다','반에서 함께 정해요'),
('K5-1-u1-X41','kor',5,'u1',ARRAY['K5-1-u1-C39']::text[],'글자가 같으면 소리의 길이도 같다고 여겨 장단으로 뜻이 갈리는 줄 모른다','길이에 따라 뜻이'),
('K5-1-u1-X42','kor',5,'u1',ARRAY['K5-1-u1-C40']::text[],'문장 속 뜻을 보지 않고 짧은소리와 긴소리를 거꾸로 고른다','뜻을 먼저 봐요')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_kor_u1_L01_basic#1','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C1',1,'mc','auto','「배려하며 대화한다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X01','K5-1-u1-X02','K5-1-u1-X30']::text[],false,'{"seq":1,"concept":"K5-1-u1-C1","difficulty":1,"kind":"mc","stem":"「배려하며 대화한다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"상대의 처지에서 생각하고 그 마음에 맞게 말과 태도를 고르는 것","correct":true},{"t":"듣기 좋은 말을 예쁘게 꾸며 많이 하는 것","mis":"K5-1-u1-X01"},{"t":"대화에서 내 생각을 끝까지 밀고 나가는 것","mis":"K5-1-u1-X02"},{"t":"상대가 말하지 않은 비밀을 알아내는 것","mis":"K5-1-u1-X30"}],"explanation":["꾸미는 기술이 아니에요.","이기려는 대화가 아니에요.","상대의 처지에서 말과 태도를 골라요."]}'::jsonb),
('g5_1_kor_u1_L01_basic#2','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C1',1,'mc','auto','도현이가 아무 말도 하지 못한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X04']::text[],false,'{"seq":2,"concept":"K5-1-u1-C1","difficulty":1,"kind":"mc","stem":"도현이가 아무 말도 하지 못한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"유나가 아픈 마음을 헤아리지 않고 말했기 때문이다","correct":true},{"t":"유나의 목소리가 너무 컸기 때문이다","mis":"K5-1-u1-X04"},{"t":"도현이가 피구를 하기 싫었기 때문이다","mis":"K5-1-u1-X04"},{"t":"도현이는 원래 말수가 적기 때문이다","mis":"K5-1-u1-X04"}],"explanation":["대화에 목소리 이야기는 없어요.","피구 이야기는 유나가 꺼냈어요.","아픈 마음을 탓하는 말로 받았어요."],"asset":{"type":"speech","turns":[{"who":"도현","text":"어제 줄넘기를 하다가 넘어져서 무릎이 까졌어. 아직도 쓰라려."},{"who":"유나","text":"(딴 곳을 보며) 그러게 조심 좀 하지. 난 오늘 피구 하러 갈 건데 넌 못 하겠네."},{"who":"도현","text":"……."}]}}'::jsonb),
('g5_1_kor_u1_L01_basic#3','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C2',1,'ox','auto','상대를 배려하며 대화하면 대화를 더 빨리 끝낼 수 있어서 좋아요.',ARRAY['K5-1-u1-X02']::text[],false,'{"seq":3,"concept":"K5-1-u1-C2","difficulty":1,"kind":"ox","stem":"상대를 배려하며 대화하면 대화를 더 빨리 끝낼 수 있어서 좋아요.","answer":"X","reason_options":[{"t":"배려는 서로 기분이 상하지 않고 대화를 이어 가게 해 주기 때문에","correct":true},{"t":"배려하면 말을 적게 해도 되기 때문에","mis":"K5-1-u1-X02"}],"mis":"K5-1-u1-X02","explanation":["빨리 끝내려는 것이 아니에요.","말의 양과도 관계없어요.","대화를 기분 좋게 이어 가요."]}'::jsonb),
('g5_1_kor_u1_L01_basic#4','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C4',1,'sa','auto','어떤 일을 풀 수 있는 실마리를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u1-C4","difficulty":1,"kind":"sa","stem":"어떤 일을 풀 수 있는 실마리를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["단서"],"explanation":["짐작에는 근거가 있어요.","그 근거를 이르는 말이에요.","단서는 어떤 일을 풀 수 있는 실마리예요."],"mis":"K5-1-u1-X04"}'::jsonb),
('g5_1_kor_u1_L01_basic#5','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C3',2,'mc','auto','서준이의 첫 말에서 생략된 내용은 무엇인가요?',ARRAY['K5-1-u1-X03','K5-1-u1-X04']::text[],false,'{"seq":5,"concept":"K5-1-u1-C3","difficulty":2,"kind":"mc","stem":"서준이의 첫 말에서 생략된 내용은 무엇인가요?","options":[{"t":"급식실에 늦게 간 까닭","correct":true},{"t":"함께 간 친구의 이름","mis":"K5-1-u1-X03"},{"t":"급식실이 있는 곳","mis":"K5-1-u1-X03"},{"t":"하린이가 물어본 까닭","mis":"K5-1-u1-X04"}],"explanation":["친구 이야기는 묻지 않았어요.","급식실 위치는 서로 알아요.","하린이가 「왜 늦게 갔어?」라고 되물었어요."],"asset":{"type":"speech","turns":[{"who":"서준","text":"오늘 급식실에 늦게 갔어."},{"who":"하린","text":"어? 그런데 왜 늦게 갔어?"},{"who":"서준","text":"청소 당번이었거든. 교실 정리를 다 하고 나서야 갔어."}]}}'::jsonb),
('g5_1_kor_u1_L01_basic#6','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C3',2,'mc','auto','대화에서 생략된 내용이 생기는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X03','K5-1-u1-X30']::text[],false,'{"seq":6,"concept":"K5-1-u1-C3","difficulty":2,"kind":"mc","stem":"대화에서 생략된 내용이 생기는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 알고 있다고 여기는 부분은 줄여서 말하기 때문이다","correct":true},{"t":"대화를 잘 못하는 사람만 말을 빼먹기 때문이다","mis":"K5-1-u1-X03"},{"t":"글로 적지 않은 말은 모두 생략된 것이기 때문이다","mis":"K5-1-u1-X03"},{"t":"모든 말에는 숨은 뜻이 있기 때문이다","mis":"K5-1-u1-X30"}],"explanation":["누구나 줄여서 말해요.","말로 한 것은 생략이 아니에요.","아는 것을 다 말하지 않아서 빈 곳이 생겨요."]}'::jsonb),
('g5_1_kor_u1_L01_basic#7','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C22',2,'match','auto','친구가 짐작한 내용과 짐작한 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-1-u1-C22","difficulty":2,"kind":"match","stem":"친구가 짐작한 내용과 짐작한 방법을 알맞게 이으세요.","pairs":[{"l":"몹시 급한 일이 있나 보다","r":"숨을 몰아쉬며 빨리 말한 것을 듣고"},{"l":"어제 늦게 잤나 보다","r":"하품하는 행동을 보고"},{"l":"우산이 없어서 그러나 보다","r":"비가 쏟아지는 상황을 보고"}],"mis":"K5-1-u1-X25","explanation":["들은 말이 단서예요.","본 행동이 단서예요.","그때의 상황도 단서가 돼요."]}'::jsonb),
('g5_1_kor_u1_L01_basic#8','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C2',2,'mc','auto','상대를 배려하며 대화하면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X02']::text[],false,'{"seq":8,"concept":"K5-1-u1-C2","difficulty":2,"kind":"mc","stem":"상대를 배려하며 대화하면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 기분이 상하지 않고 대화를 이어 갈 수 있다","correct":true},{"t":"대화에서 이길 수 있다","mis":"K5-1-u1-X02"},{"t":"대화를 훨씬 짧게 끝낼 수 있다","mis":"K5-1-u1-X02"},{"t":"상대가 내 말을 무조건 따르게 된다","mis":"K5-1-u1-X02"}],"explanation":["이기고 지는 대화가 아니에요.","짧게 끝내려는 것이 아니에요.","관계를 지키며 대화를 이어 가요."]}'::jsonb),
('g5_1_kor_u1_L01_basic#9','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C1',2,'error','auto','유나의 말과 태도를 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X08','K5-1-u1-X10']::text[],false,'{"seq":9,"concept":"K5-1-u1-C1","difficulty":2,"kind":"error","stem":"유나의 말과 태도를 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「유나는 말이 짧아서 배려하지 않은 것이다.」","correct":true,"mis_target":"K5-1-u1-X11"},{"t":"「아픈 마음을 헤아리지 않고 잘못을 먼저 탓했다.」","mis":"K5-1-u1-X08"},{"t":"「딴 곳을 보며 말해 마음이 전해지지 않았다.」","mis":"K5-1-u1-X10"}],"explanation":["잘못을 먼저 탓했어요.","딴 곳을 본 태도도 문제예요.","말의 길이가 문제가 아니라 마음을 헤아리지 않은 것이 문제예요."],"asset":{"type":"speech","turns":[{"who":"도현","text":"어제 줄넘기를 하다가 넘어져서 무릎이 까졌어. 아직도 쓰라려."},{"who":"유나","text":"(딴 곳을 보며) 그러게 조심 좀 하지. 난 오늘 피구 하러 갈 건데 넌 못 하겠네."},{"who":"도현","text":"……."}]}}'::jsonb),
('g5_1_kor_u1_L01_basic#10','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C5',3,'mc','auto','이 단원에서 배우는 두 가지가 함께 갖추어져야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X05']::text[],false,'{"seq":10,"concept":"K5-1-u1-C5","difficulty":3,"kind":"mc","stem":"이 단원에서 배우는 두 가지가 함께 갖추어져야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"배려해야 상대의 말과 행동을 눈여겨보게 되고, 그래야 말하지 않은 마음도 짐작할 수 있기 때문이다","correct":true},{"t":"두 가지는 서로 다른 때에만 쓰기 때문이다","mis":"K5-1-u1-X05"},{"t":"짐작만 잘하면 배려는 하지 않아도 되기 때문이다","mis":"K5-1-u1-X05"},{"t":"배려하면 짐작할 필요가 없어지기 때문이다","mis":"K5-1-u1-X05"}],"explanation":["함께 쓰여요.","짐작만으로는 마음이 다쳐요.","두 가지가 함께여야 대화가 오가요."]}'::jsonb),
('g5_1_kor_u1_L01_challenge#1','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C4',2,'mc','auto','「짐작에는 늘 근거가 있다」에서 근거가 되는 것은 어느 것인가요?',ARRAY['K5-1-u1-X04','K5-1-u1-X26']::text[],false,'{"seq":1,"concept":"K5-1-u1-C4","difficulty":2,"kind":"mc","stem":"「짐작에는 늘 근거가 있다」에서 근거가 되는 것은 어느 것인가요?","options":[{"t":"말 · 행동 · 경험과 배경지식 · 상황 같은 단서","correct":true},{"t":"그냥 드는 느낌","mis":"K5-1-u1-X04"},{"t":"친구들이 가장 많이 고른 생각","mis":"K5-1-u1-X26"},{"t":"내가 바라는 대로의 결과","mis":"K5-1-u1-X04"}],"explanation":["느낌은 근거가 아니에요.","많이 골랐다고 근거가 되지는 않아요.","단서가 짐작의 근거예요."]}'::jsonb),
('g5_1_kor_u1_L01_challenge#2','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C3',2,'ox','auto','말에 드러나지 않은 부분은 대화에서 아무 뜻이 없어요.',ARRAY['K5-1-u1-X03']::text[],false,'{"seq":2,"concept":"K5-1-u1-C3","difficulty":2,"kind":"ox","stem":"말에 드러나지 않은 부분은 대화에서 아무 뜻이 없어요.","answer":"X","reason_options":[{"t":"서로 안다고 여겨 줄인 부분에 중요한 내용이 담기기도 하기 때문에","correct":true},{"t":"말한 것만이 대화의 전부이기 때문에","mis":"K5-1-u1-X03"}],"mis":"K5-1-u1-X03","explanation":["빈 곳에도 뜻이 있어요.","서준이의 첫 말에도 까닭이 빠져 있었어요.","생략된 내용을 짐작하며 들어요."]}'::jsonb),
('g5_1_kor_u1_L01_challenge#3','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C1',3,'mc','auto','유나가 배려하며 대답했다면 어떤 말이 알맞았을까요?',ARRAY['K5-1-u1-X08','K5-1-u1-X13','K5-1-u1-X01']::text[],false,'{"seq":3,"concept":"K5-1-u1-C1","difficulty":3,"kind":"mc","stem":"유나가 배려하며 대답했다면 어떤 말이 알맞았을까요?","options":[{"t":"「많이 아팠겠다. 오늘은 무리하지 말고 쉬어. 준비물 챙기는 것 도와줄까?」","correct":true},{"t":"「그러니까 조심했어야지. 다음엔 넘어지지 마.」","mis":"K5-1-u1-X08"},{"t":"(공책을 보며) 「아, 그래. 아프겠다.」","mis":"K5-1-u1-X13"},{"t":"「나도 저번에 넘어졌는데 나는 하나도 안 아팠어.」","mis":"K5-1-u1-X01"}],"explanation":["여전히 잘못을 탓해요.","딴 곳을 보는 말은 마음이 전해지지 않아요.","아픈 마음을 헤아리고 도울 방법을 보태요."],"asset":{"type":"speech","turns":[{"who":"도현","text":"어제 줄넘기를 하다가 넘어져서 무릎이 까졌어. 아직도 쓰라려."},{"who":"유나","text":"(딴 곳을 보며) 그러게 조심 좀 하지. 난 오늘 피구 하러 갈 건데 넌 못 하겠네."},{"who":"도현","text":"……."}]}}'::jsonb),
('g5_1_kor_u1_L01_challenge#4','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C3',3,'mc','auto','대화에서 생략된 내용을 짐작하는 힘이 필요한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X30','K5-1-u1-X27']::text[],false,'{"seq":4,"concept":"K5-1-u1-C3","difficulty":3,"kind":"mc","stem":"대화에서 생략된 내용을 짐작하는 힘이 필요한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리는 아는 것을 모두 말하지 않아 빠진 내용을 채워야 서로 이해할 수 있기 때문이다","correct":true},{"t":"상대의 비밀을 알아내야 하기 때문이다","mis":"K5-1-u1-X30"},{"t":"상대가 하는 말은 모두 거짓이기 때문이다","mis":"K5-1-u1-X30"},{"t":"짐작을 하면 상대의 말을 덜 들어도 되기 때문이다","mis":"K5-1-u1-X27"}],"explanation":["비밀을 캐려는 것이 아니에요.","말을 의심하는 것이 아니에요.","빈 곳을 채워 서로 이해해요."]}'::jsonb),
('g5_1_kor_u1_L01_challenge#5','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C22',3,'mc','auto','비가 쏟아지는 것을 보고 「친구가 우산이 없어서 저러나 보다」라고 짐작했어요. 이때 쓴 단서는 어느 것인가요?',ARRAY['K5-1-u1-X25','K5-1-u1-X04']::text[],false,'{"seq":5,"concept":"K5-1-u1-C22","difficulty":3,"kind":"mc","stem":"비가 쏟아지는 것을 보고 「친구가 우산이 없어서 저러나 보다」라고 짐작했어요. 이때 쓴 단서는 어느 것인가요?","options":[{"t":"그때의 상황","correct":true},{"t":"친구가 한 말","mis":"K5-1-u1-X25"},{"t":"친구의 표정","mis":"K5-1-u1-X25"},{"t":"내가 어제 꾼 꿈","mis":"K5-1-u1-X04"}],"explanation":["친구는 아무 말도 하지 않았어요.","표정 이야기는 없어요.","비가 쏟아지는 상황을 보았어요."]}'::jsonb),
('g5_1_kor_u1_L01_challenge#6','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C2',3,'error','auto','배려하며 대화하는 까닭을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X02','K5-1-u1-X01']::text[],false,'{"seq":6,"concept":"K5-1-u1-C2","difficulty":3,"kind":"error","stem":"배려하며 대화하는 까닭을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「배려하면 말다툼에서 이길 수 있으니까.」","correct":true,"mis_target":"K5-1-u1-X02"},{"t":"「상대의 마음이 다치지 않게 하려고.」","mis":"K5-1-u1-X01"},{"t":"「대화를 기분 좋게 이어 가려고.」","mis":"K5-1-u1-X02"}],"explanation":["마음을 지켜요.","대화를 이어 가요.","배려는 이기려는 기술이 아니에요."]}'::jsonb),
('g5_1_kor_u1_L01_challenge#7','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C26',3,'mc','auto','하린이가 「왜 늦게 갔어?」라고 물은 일에서 알 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u1-X30','K5-1-u1-X07','K5-1-u1-X04']::text[],false,'{"seq":7,"concept":"K5-1-u1-C26","difficulty":3,"kind":"mc","stem":"하린이가 「왜 늦게 갔어?」라고 물은 일에서 알 수 있는 것은 어느 것인가요?","options":[{"t":"빠진 내용이 있으면 물어 확인하며 대화를 이어 갈 수 있다","correct":true},{"t":"모든 말에는 숨은 뜻이 있다","mis":"K5-1-u1-X30"},{"t":"묻는 것은 배려가 아니다","mis":"K5-1-u1-X07"},{"t":"서준이가 거짓말을 했다","mis":"K5-1-u1-X04"}],"explanation":["숨은 뜻을 캐려던 게 아니에요.","되묻는 것도 잘 듣는 태도예요.","물어 확인해서 빈 곳을 채웠어요."],"asset":{"type":"speech","turns":[{"who":"서준","text":"오늘 급식실에 늦게 갔어."},{"who":"하린","text":"어? 그런데 왜 늦게 갔어?"},{"who":"서준","text":"청소 당번이었거든. 교실 정리를 다 하고 나서야 갔어."}]}}'::jsonb),
('g5_1_kor_u1_L01_challenge#8','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C22',4,'mc','auto','친구가 교실에 들어오며 「아, 춥다.」 하고 손을 비볐어요. 여러 단서를 함께 써서 짐작한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X27','K5-1-u1-X04']::text[],false,'{"seq":8,"concept":"K5-1-u1-C22","difficulty":4,"kind":"mc","stem":"친구가 교실에 들어오며 「아, 춥다.」 하고 손을 비볐어요. 여러 단서를 함께 써서 짐작한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「춥다고 말하며 손을 비비는 걸 보니, 바람이 찬 길을 걸어왔나 보다.」","correct":true},{"t":"「춥다고 했으니 감기에 걸렸겠다.」","mis":"K5-1-u1-X27"},{"t":"「손을 비비니 손을 다쳤나 보다.」","mis":"K5-1-u1-X04"},{"t":"「나는 안 추우니 친구도 춥지 않을 거야.」","mis":"K5-1-u1-X04"}],"explanation":["드러난 것을 넘어 넘겨짚었어요.","단서와 이어지지 않아요.","말과 행동을 함께 단서로 썼어요."]}'::jsonb),
('g5_1_kor_u1_L01_challenge#9','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C1',4,'essay','teacher','최근에 친구나 가족과 나눈 대화 하나를 떠올려, 상대를 배려한 점이나 배려하지 못한 점을 쓰고 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u1-C1","difficulty":4,"kind":"essay","stem":"최근에 친구나 가족과 나눈 대화 하나를 떠올려, 상대를 배려한 점이나 배려하지 못한 점을 쓰고 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 어제 동생이 블록 탑이 무너졌다고 울 때 「그거 다시 쌓으면 되잖아.」라고 했다. 동생이 오래 쌓은 탑이라 속상했을 텐데 그 마음을 헤아리지 않고 가볍게 넘겼다. 「오래 쌓았는데 속상하겠다. 같이 다시 쌓을까?」라고 말했으면 좋았겠다.","scoring_points":["대화 장면을 떠올려 썼는가","배려한 점이나 배려하지 못한 점을 썼는가","상대의 마음과 이어 까닭을 썼는가"]},"explanation":["최근 대화를 떠올려요.","상대의 처지에서 다시 봐요.","까닭을 마음과 이어 써요."]}'::jsonb),
('g5_1_kor_u1_L01_challenge#10','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C5',4,'essay','teacher','「배려하며 대화하기」와 「생략된 내용을 짐작하며 대화하기」가 각각 무엇인지 쓰고, 두 가지가 함께 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u1-C5","difficulty":4,"kind":"essay","stem":"「배려하며 대화하기」와 「생략된 내용을 짐작하며 대화하기」가 각각 무엇인지 쓰고, 두 가지가 함께 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 배려하며 대화하기는 상대의 처지에서 생각하고 그 마음에 맞게 말과 태도를 고르는 것이다. 짐작하며 대화하기는 말 · 행동 · 경험 · 상황을 단서로 말에 드러나지 않은 내용을 채우는 것이다. 상대를 배려해야 말과 행동을 눈여겨보게 되고, 눈여겨보아야 말하지 않은 마음을 짐작할 수 있으므로 두 가지가 함께 갖추어질 때 대화가 오간다.","scoring_points":["배려하며 대화하기의 뜻을 썼는가","짐작하며 대화하기의 뜻을 썼는가","함께 필요한 까닭을 썼는가"]},"explanation":["두 가지 뜻을 떠올려요.","단서를 함께 써요.","서로 돕는 관계로 정리해요."]}'::jsonb),
('g5_1_kor_u1_L02_basic#1','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C6',1,'mc','auto','지완이가 말을 멈춘 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X04','K5-1-u1-X09']::text[],false,'{"seq":1,"concept":"K5-1-u1-C6","difficulty":1,"kind":"mc","stem":"지완이가 말을 멈춘 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나경이가 말을 끊고 다른 이야기를 꺼내서","correct":true},{"t":"숙제 이야기가 어려워서","mis":"K5-1-u1-X04"},{"t":"지완이가 원래 말을 짧게 해서","mis":"K5-1-u1-X04"},{"t":"나경이가 목소리를 높여서","mis":"K5-1-u1-X09"}],"explanation":["숙제가 어렵다는 말은 없어요.","지완이는 말을 이어 가려 했어요.","나경이가 필통 이야기로 넘어갔어요."],"asset":{"type":"speech","turns":[{"who":"지완","text":"어제 만들기 숙제를 하다가 풀이 다 굳어서……."},{"who":"나경","text":"(지완이 쪽을 보지 않고 필통을 만지며) 어? 너 필통 새로 샀네? 그거 어디서 샀어?"},{"who":"지완","text":"……."}]}}'::jsonb),
('g5_1_kor_u1_L02_basic#2','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C6',1,'mc','auto','배려하며 대화하는 방법에 들지 않는 것은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X08','K5-1-u1-X09']::text[],false,'{"seq":2,"concept":"K5-1-u1-C6","difficulty":1,"kind":"mc","stem":"배려하며 대화하는 방법에 들지 않는 것은 어느 것인가요?","options":[{"t":"내 이야기를 먼저 끝내기","correct":true},{"t":"상대의 말을 집중해서 듣기","mis":"K5-1-u1-X06"},{"t":"상대의 기분을 고려하며 말하기","mis":"K5-1-u1-X08"},{"t":"대화 예절 지키기","mis":"K5-1-u1-X09"}],"explanation":["집중해서 듣기는 배려예요.","기분을 고려하는 것도 배려예요.","내 이야기를 앞세우면 상대가 빠져요."]}'::jsonb),
('g5_1_kor_u1_L02_basic#3','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C10',1,'ox','auto','말을 바르게만 하면 딴 곳을 보며 말해도 마음이 전해져요.',ARRAY['K5-1-u1-X10']::text[],false,'{"seq":3,"concept":"K5-1-u1-C10","difficulty":1,"kind":"ox","stem":"말을 바르게만 하면 딴 곳을 보며 말해도 마음이 전해져요.","answer":"X","reason_options":[{"t":"표정과 행동도 말이어서 딴 곳을 보면 마음이 전해지지 않기 때문에","correct":true},{"t":"마음은 말로만 전해지기 때문에","mis":"K5-1-u1-X10"}],"mis":"K5-1-u1-X10","explanation":["태도도 말이에요.","눈을 맞추면 받아들여졌다고 느껴요.","배려는 태도에서 드러나요."]}'::jsonb),
('g5_1_kor_u1_L02_basic#4','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C13',1,'match','auto','상황과 그 상황에 어울리는 배려의 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u1-C13","difficulty":1,"kind":"match","stem":"상황과 그 상황에 어울리는 배려의 말을 알맞게 이으세요.","pairs":[{"l":"친구가 시험을 못 봐 속상해할 때","r":"많이 아쉬웠겠다. 그동안 애썼잖아."},{"l":"친구가 상을 받아 기뻐할 때","r":"정말 잘됐다. 나도 기분이 좋아."},{"l":"친구가 부탁을 어렵게 꺼낼 때","r":"편하게 말해도 돼. 무슨 일인데?"}],"mis":"K5-1-u1-X14","explanation":["속상할 땐 마음을 알아줘요.","기쁠 땐 함께 기뻐해요.","어려워할 땐 편하게 해 줘요."]}'::jsonb),
('g5_1_kor_u1_L02_basic#5','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C7',2,'mc','auto','나경이가 「아, 그래서 어떻게 했어? 계속 말해 봐.」라고 한 말이 좋은 까닭은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X02','K5-1-u1-X08']::text[],false,'{"seq":5,"concept":"K5-1-u1-C7","difficulty":2,"kind":"mc","stem":"나경이가 「아, 그래서 어떻게 했어? 계속 말해 봐.」라고 한 말이 좋은 까닭은 어느 것인가요?","options":[{"t":"지완이가 하던 말을 이어서 할 수 있게 되물었기 때문이다","correct":true},{"t":"나경이가 자기 이야기를 꺼냈기 때문이다","mis":"K5-1-u1-X06"},{"t":"대화를 빨리 끝냈기 때문이다","mis":"K5-1-u1-X02"},{"t":"지완이의 잘못을 짚어 주었기 때문이다","mis":"K5-1-u1-X08"}],"explanation":["자기 이야기는 꺼내지 않았어요.","오히려 대화가 이어졌어요.","되묻기로 말할 길을 열어 주었어요."],"asset":{"type":"speech","turns":[{"who":"지완","text":"어제 만들기 숙제를 하다가 풀이 다 굳어서……."},{"who":"나경","text":"(지완이를 바라보며 고개를 끄덕이고) 아, 그래서 어떻게 했어? 계속 말해 봐."},{"who":"지완","text":"밤늦게까지 다시 붙였는데, 그래도 다 못 끝냈어."}]}}'::jsonb),
('g5_1_kor_u1_L02_basic#6','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C8',2,'mc','auto','태윤이가 대답 ㉯를 듣고 고마워한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X02','K5-1-u1-X08']::text[],false,'{"seq":6,"concept":"K5-1-u1-C8","difficulty":2,"kind":"mc","stem":"태윤이가 대답 ㉯를 듣고 고마워한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"실수를 탓하지 않고 마음을 헤아려 주어서","correct":true},{"t":"서아가 리코더를 더 잘 불어서","mis":"K5-1-u1-X02"},{"t":"대답을 빨리 해 주어서","mis":"K5-1-u1-X02"},{"t":"서아가 바쁘다고 솔직하게 말해서","mis":"K5-1-u1-X08"}],"explanation":["잘 부는 것과는 관계없어요.","빠르기 때문이 아니에요.","같은 경험을 나누며 탓하지 않았어요."],"asset":{"type":"passage","lines":["태윤 — 「리코더 운지가 자꾸 틀려. 좀 알려 줄 수 있어?」","서아의 대답 ㉮ — 「그걸 아직도 못 해? 난 지금 바빠.」","서아의 대답 ㉯ — 「나도 처음에는 계속 틀렸어. 여기 손가락부터 같이 해 볼까?」"],"title":"도움을 부탁하는 상황"}}'::jsonb),
('g5_1_kor_u1_L02_basic#7','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C11',2,'ox','auto','배려하며 대화하는 방법은 네 가지뿐이라서 그대로 외워 써야 해요.',ARRAY['K5-1-u1-X12']::text[],false,'{"seq":7,"concept":"K5-1-u1-C11","difficulty":2,"kind":"ox","stem":"배려하며 대화하는 방법은 네 가지뿐이라서 그대로 외워 써야 해요.","answer":"X","reason_options":[{"t":"상황과 상대에 따라 배려하는 방법이 달라지고 내가 찾은 방법도 배려이기 때문에","correct":true},{"t":"정해진 방법을 따라야 실수가 없기 때문에","mis":"K5-1-u1-X12"}],"mis":"K5-1-u1-X12","explanation":["외울 공식이 아니에요.","상황마다 달라져요.","중요한 것은 상대를 향한 마음이에요."]}'::jsonb),
('g5_1_kor_u1_L02_basic#8','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C14',2,'mc','auto','다율이의 말에서 고칠 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X10','K5-1-u1-X15']::text[],false,'{"seq":8,"concept":"K5-1-u1-C14","difficulty":2,"kind":"mc","stem":"다율이의 말에서 고칠 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"위로가 필요한 때에 까닭을 따지고 속상한 마음을 가볍게 넘겼다","correct":true},{"t":"말이 너무 길어서 은우가 지루했다","mis":"K5-1-u1-X11"},{"t":"목소리가 작아서 들리지 않았다","mis":"K5-1-u1-X10"},{"t":"다음에 잘하라고 해서 은우가 신났다","mis":"K5-1-u1-X15"}],"explanation":["말은 오히려 짧았어요.","목소리 이야기는 없어요.","속상한 마음을 먼저 받아 주지 않았어요."],"asset":{"type":"speech","turns":[{"who":"은우","text":"달리기 대회에서 넘어져서 너무 속상해. 한 달이나 연습했는데."},{"who":"다율","text":"연습을 덜 했나 보지. 다음에 잘하면 되잖아."}]}}'::jsonb),
('g5_1_kor_u1_L02_basic#9','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C9',2,'mc','auto','대화 예절을 지킨 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X09']::text[],false,'{"seq":9,"concept":"K5-1-u1-C9","difficulty":2,"kind":"mc","stem":"대화 예절을 지킨 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구가 말을 마칠 때까지 기다렸다가 차례를 지켜 말한다","correct":true},{"t":"친구 말이 길면 중간에 끼어들어 정리해 준다","mis":"K5-1-u1-X06"},{"t":"친한 사이니까 놀리는 말을 섞어 말한다","mis":"K5-1-u1-X09"},{"t":"마음만 있으면 말씨는 아무래도 괜찮다고 여긴다","mis":"K5-1-u1-X09"}],"explanation":["끼어들면 말이 끊겨요.","놀리는 말은 마음을 다치게 해요.","차례를 지키고 바른 말씨를 써요."]}'::jsonb),
('g5_1_kor_u1_L02_basic#10','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C12',3,'mc','auto','두 말 가운데 「진심이 담긴 말」이 상대에게 더 잘 전해지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X13','K5-1-u1-X10']::text[],false,'{"seq":10,"concept":"K5-1-u1-C12","difficulty":3,"kind":"mc","stem":"두 말 가운데 「진심이 담긴 말」이 상대에게 더 잘 전해지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하던 일을 멈추고 바라보며 상대의 처지를 실제로 생각했기 때문이다","correct":true},{"t":"말이 더 길기 때문이다","mis":"K5-1-u1-X11"},{"t":"「힘들었겠다」라는 낱말을 썼기 때문이다","mis":"K5-1-u1-X13"},{"t":"휴대 전화로 더 빨리 답했기 때문이다","mis":"K5-1-u1-X10"}],"explanation":["길이 때문이 아니에요.","같은 낱말도 마음이 없으면 전해지지 않아요.","흉내보다 진심이 먼저예요."],"asset":{"type":"passage","lines":["형식만 갖춘 말 — (휴대 전화를 보며) 「아, 그렇구나. 힘들었겠다.」","진심이 담긴 말 — (하던 일을 멈추고 바라보며) 「그랬구나. 언제부터 그랬어?」"],"title":"같은 위로, 다른 말"}}'::jsonb),
('g5_1_kor_u1_L02_challenge#1','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C10',2,'mc','auto','배려가 드러나는 모습을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X10','K5-1-u1-X07']::text[],false,'{"seq":1,"concept":"K5-1-u1-C10","difficulty":2,"kind":"mc","stem":"배려가 드러나는 모습을 바르게 말한 것은 어느 것인가요?","options":[{"t":"말수가 적어도 눈을 맞추고 고개를 끄덕이면 상대는 말이 받아들여졌다고 느낀다","correct":true},{"t":"배려는 말을 많이 해 줄수록 커진다","mis":"K5-1-u1-X11"},{"t":"표정은 대화와 관계가 없다","mis":"K5-1-u1-X10"},{"t":"듣는 사람은 가만히만 있으면 된다","mis":"K5-1-u1-X07"}],"explanation":["말의 양이 아니에요.","표정도 말이에요.","태도에서 배려가 드러나요."]}'::jsonb),
('g5_1_kor_u1_L02_challenge#2','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C7',2,'ox','auto','잘 듣는다는 것은 아무 반응 없이 가만히 있는 거예요.',ARRAY['K5-1-u1-X07']::text[],false,'{"seq":2,"concept":"K5-1-u1-C7","difficulty":2,"kind":"ox","stem":"잘 듣는다는 것은 아무 반응 없이 가만히 있는 거예요.","answer":"X","reason_options":[{"t":"이어서 말하도록 되묻거나 고개를 끄덕이는 반응도 잘 듣는 태도이기 때문에","correct":true},{"t":"듣는 사람이 말을 하면 끼어드는 것이기 때문에","mis":"K5-1-u1-X07"}],"mis":"K5-1-u1-X07","explanation":["되묻기는 끼어들기와 달라요.","끄덕임도 듣고 있다는 신호예요.","반응하며 들어요."]}'::jsonb),
