('g5_1_kor_u1_L11_challenge#3','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C35',3,'mc','auto','조언을 건네는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X38']::text[],false,'{"seq":3,"concept":"K5-1-u1-C35","difficulty":3,"kind":"mc","stem":"조언을 건네는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"마음을 알아주는 말 → 내가 해 본 방법 → 고르도록 권하는 말투","correct":true},{"t":"내가 해 본 방법 → 잘못 짚기 → 시키는 말투","mis":"K5-1-u1-X38"},{"t":"권하는 말투 → 마음 알아주기 → 내 고민 이야기","mis":"K5-1-u1-X38"},{"t":"잘못 짚기 → 마음 알아주기 → 지켜야 할 규칙","mis":"K5-1-u1-X38"}],"explanation":["잘못 짚기는 넣지 않아요.","차례가 뒤섞였어요.","마음 → 방법 → 권하기예요."]}'::jsonb),
('g5_1_kor_u1_L11_challenge#4','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C33',3,'mc','auto','고민 상담소에서 배려하며 듣기와 짐작하기를 함께 쓴 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X29','K5-1-u1-X36']::text[],false,'{"seq":4,"concept":"K5-1-u1-C33","difficulty":3,"kind":"mc","stem":"고민 상담소에서 배려하며 듣기와 짐작하기를 함께 쓴 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"끝까지 듣고 마음을 알아준 뒤, 글에 적히지 않은 마음을 짐작해 맞는지 물어본다","correct":true},{"t":"고민을 다 듣기 전에 해결 방법부터 말한다","mis":"K5-1-u1-X06"},{"t":"짐작한 마음을 사실처럼 정해 말한다","mis":"K5-1-u1-X29"},{"t":"고민을 재미있게 다른 친구에게 들려준다","mis":"K5-1-u1-X36"}],"explanation":["끝까지 듣지 않았어요.","짐작은 물어 확인해요.","고민은 옮기지 않아요."]}'::jsonb),
