('g5_1_kor_u1_review_a#9','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C6',2,'mc','auto','찬솔이의 말과 태도에서 문제점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X09','K5-1-u1-X07']::text[],false,'{"seq":9,"concept":"K5-1-u1-C6","difficulty":2,"kind":"mc","stem":"찬솔이의 말과 태도에서 문제점으로 알맞은 것은 어느 것인가요?","options":[{"t":"새별이의 말을 끝까지 듣지 않고 다른 이야기로 넘어갔다","correct":true},{"t":"새별이에게 너무 길게 말했다","mis":"K5-1-u1-X11"},{"t":"새별이에게 존댓말을 썼다","mis":"K5-1-u1-X09"},{"t":"새별이의 말을 이어서 물었다","mis":"K5-1-u1-X07"}],"explanation":["말은 오히려 짧았어요.","존댓말 이야기는 없어요.","숙제 이야기로 넘어가 말을 끊었어요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb),
