('g5_1_kor_u1_review_a#11','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C22',2,'mc','auto','다래가 「혹시 발목 아파?」라고 짐작한 단서로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X24','K5-1-u1-X25','K5-1-u1-X28']::text[],false,'{"seq":11,"concept":"K5-1-u1-C22","difficulty":2,"kind":"mc","stem":"다래가 「혹시 발목 아파?」라고 짐작한 단서로 알맞은 것은 어느 것인가요?","options":[{"t":"찬솔이가 발목을 만지작거리는 행동","correct":true},{"t":"피구를 한다는 다래의 말","mis":"K5-1-u1-X24"},{"t":"체육 시간이라는 때","mis":"K5-1-u1-X25"},{"t":"찬솔이가 어제 계단에 간 일","mis":"K5-1-u1-X28"}],"explanation":["그건 다래가 한 말이에요.","때만으로는 알 수 없어요.","계단 이야기는 짐작 뒤에 들었어요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb),
