('g5_1_kor_u1_review_a#13','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C18',2,'mc','auto','다래의 준비에서 빈칸에 들어갈 항목은 어느 것인가요?',ARRAY['K5-1-u1-X19']::text[],false,'{"seq":13,"concept":"K5-1-u1-C18","difficulty":2,"kind":"mc","stem":"다래의 준비에서 빈칸에 들어갈 항목은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"언제","mis":"K5-1-u1-X19"},{"t":"어디에서","mis":"K5-1-u1-X19"},{"t":"무슨 일을","mis":"K5-1-u1-X19"}],"explanation":["「지난 일요일 오후에」가 있어요.","「아파트 앞 공원에서」가 있어요.","그때 든 마음이 비어 있어요."],"asset":{"type":"passage","lines":["대화 주제 — 동생에게 처음으로 자전거 타는 법을 알려 준 일","언제 — 지난 일요일 오후에","어디에서 — 아파트 앞 공원에서","무슨 일을 — 동생 자전거 뒤를 잡고 따라 뛰다가 살며시 손을 놓았는데,","　　동생이 혼자서 공원 끝까지 달렸다.","생각이나 느낌 — ?"],"title":"다래가 준비한 내용"}}'::jsonb),
('g5_1_kor_u1_review_a#14','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C28',2,'mc','auto','「우산꽂이의 쪽지」 앞부분에서 글쓴이가 일부러 밝히지 않은 것은 어느 것인가요?',ARRAY['K5-1-u1-X31']::text[],false,'{"seq":14,"concept":"K5-1-u1-C28","difficulty":2,"kind":"mc","stem":"「우산꽂이의 쪽지」 앞부분에서 글쓴이가 일부러 밝히지 않은 것은 어느 것인가요?","options":[{"t":"노란 우산을 꽂아 둔 사람이 누구인지","correct":true},{"t":"비가 언제 쏟아졌는지","mis":"K5-1-u1-X31"},{"t":"해람이가 우산을 챙기지 않은 까닭","mis":"K5-1-u1-X31"},{"t":"쪽지에 적힌 말","mis":"K5-1-u1-X31"}],"explanation":["하교 시간이라고 나와 있어요.","그냥 뛰어나왔다고 나와 있어요.","누가 두었는지는 빈 곳이에요."],"asset":{"type":"passage","lines":["하교 시간에 갑자기 비가 쏟아졌다. 해람이는 현관에서 발을 동동 굴렀다.","아침에 엄마가 우산을 챙기라고 했는데, 그냥 뛰어나온 것이다.","그때 우산꽂이에 꽂힌 노란 우산 하나가 눈에 들어왔다.","손잡이에는 쪽지가 감겨 있었다. 「해람이에게 — 내일 돌려줘도 돼.」","쪽지의 글씨는 동글동글했다. 해람이는 어디서 본 듯한 글씨라고 생각했다."],"title":"「우산꽂이의 쪽지」 앞부분"}}'::jsonb),
('g5_1_kor_u1_review_a#15','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C30',2,'mc','auto','담우가 「나는 집이 가까워서 괜찮아.」라고 한 말에 생략된 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X33']::text[],false,'{"seq":15,"concept":"K5-1-u1-C30","difficulty":2,"kind":"mc","stem":"담우가 「나는 집이 가까워서 괜찮아.」라고 한 말에 생략된 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"우산을 빌려준 뒤 자기는 비를 맞고 갔다는 것","correct":true},{"t":"담우는 비를 아주 좋아한다는 것","mis":"K5-1-u1-X33"},{"t":"담우는 우산이 없다는 것","mis":"K5-1-u1-X33"},{"t":"해람이가 미웠다는 것","mis":"K5-1-u1-X33"}],"explanation":["좋아한다는 단서가 없어요.","우산을 내주었어요.","재채기와 잠긴 목소리가 단서예요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb),
('g5_1_kor_u1_review_a#16','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C34',2,'mc','auto','고민 ④에서 짐작할 수 있는 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X37']::text[],false,'{"seq":16,"concept":"K5-1-u1-C34","difficulty":2,"kind":"mc","stem":"고민 ④에서 짐작할 수 있는 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"짝에게 서운하지만 사이가 나빠질까 봐 걱정된다","correct":true},{"t":"짝과 물건을 나누어 써서 즐겁다","mis":"K5-1-u1-X37"},{"t":"짝이 아주 밉다","mis":"K5-1-u1-X37"},{"t":"물건에 관심이 없다","mis":"K5-1-u1-X37"}],"explanation":["즐겁다는 단서가 없어요.","사이를 걱정하고 있어요.","「불편합니다」가 단서예요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb),
('g5_1_kor_u1_review_a#17','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C14',3,'mc','auto','찬솔이의 말을 배려하는 말로 알맞게 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u1-X15','K5-1-u1-X13','K5-1-u1-X08']::text[],false,'{"seq":17,"concept":"K5-1-u1-C14","difficulty":3,"kind":"mc","stem":"찬솔이의 말을 배려하는 말로 알맞게 바꾼 것은 어느 것인가요?","options":[{"t":"「할머니께서 주신 거라 속상하겠다. 숙제는 나중에 하고 같이 찾아보자.」","correct":true},{"t":"「잃어버린 건 어쩔 수 없잖아.」","mis":"K5-1-u1-X15"},{"t":"(태블릿을 보며) 「아, 속상하겠다.」","mis":"K5-1-u1-X13"},{"t":"「그러게 잘 챙겼어야지.」","mis":"K5-1-u1-X08"}],"explanation":["마음을 가볍게 넘겼어요.","딴 곳을 보는 말은 전해지지 않아요.","마음을 받아 주고 도울 방법을 보탰어요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb),
('g5_1_kor_u1_review_a#18','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C23',3,'mc','auto','찬솔이의 「아…… 그래.」를 듣고 다른 친구가 「피구가 싫은가 보다」라고 짐작했어요. 이 짐작에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-1-u1-X26','K5-1-u1-X04','K5-1-u1-X29']::text[],false,'{"seq":18,"concept":"K5-1-u1-C23","difficulty":3,"kind":"mc","stem":"찬솔이의 「아…… 그래.」를 듣고 다른 친구가 「피구가 싫은가 보다」라고 짐작했어요. 이 짐작에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「무엇을 보고 그렇게 생각했는지 서로 말해 보고 찬솔이에게 물어 확인하자.」","correct":true},{"t":"「다래가 맞혔으니 네 짐작은 틀렸어.」","mis":"K5-1-u1-X26"},{"t":"「짐작은 아무렇게나 해도 돼.」","mis":"K5-1-u1-X04"},{"t":"「둘 다 짐작했으니 묻지 않아도 돼.」","mis":"K5-1-u1-X29"}],"explanation":["맞고 틀림만 따지지 않아요.","근거가 있어야 해요.","단서를 견주고 물어 확인해요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb),
('g5_1_kor_u1_review_a#19','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C31',3,'mc','auto','「우산꽂이의 쪽지」를 차례대로 알맞게 간추린 것은 어느 것인가요?',ARRAY['K5-1-u1-X34']::text[],false,'{"seq":19,"concept":"K5-1-u1-C31","difficulty":3,"kind":"mc","stem":"「우산꽂이의 쪽지」를 차례대로 알맞게 간추린 것은 어느 것인가요?","options":[{"t":"우산이 없어 다급한 해람이가 쪽지 달린 노란 우산을 발견함 → 다음 날 담우의 재채기와 글씨를 봄 → 우산을 돌려주며 담우가 빌려준 것을 알게 됨","correct":true},{"t":"담우가 웃음 → 비가 쏟아짐 → 알림장을 봄","mis":"K5-1-u1-X34"},{"t":"현관에서 발을 동동 구름 → 엄마가 우산을 챙기라고 함 → 쪽지가 감겨 있음","mis":"K5-1-u1-X34"},{"t":"담우가 재채기를 함 → 노란 우산을 발견함 → 비가 쏟아짐","mis":"K5-1-u1-X34"}],"explanation":["차례가 뒤섞였어요.","앞부분만 늘어놓았어요.","처음 · 가운데 · 끝을 차례대로 골랐어요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb),
('g5_1_kor_u1_review_a#20','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C35',3,'mc','auto','고민 ④에 대한 조언 가운데 세 가지 요령을 모두 갖춘 것은 어느 것인가요?',ARRAY['K5-1-u1-X38','K5-1-u1-X39']::text[],false,'{"seq":20,"concept":"K5-1-u1-C35","difficulty":3,"kind":"mc","stem":"고민 ④에 대한 조언 가운데 세 가지 요령을 모두 갖춘 것은 어느 것인가요?","options":[{"t":"「혼자 참느라 불편했겠다. 나는 「쓰기 전에 말해 줄래?」라고 웃으며 말해 봤더니 괜찮았어. 너도 해 보면 어떨까?」","correct":true},{"t":"「혼자 참느라 불편했겠다.」","mis":"K5-1-u1-X38"},{"t":"「쓰기 전에 말해 달라고 해. 꼭.」","mis":"K5-1-u1-X38"},{"t":"「나도 그런 적 있어. 그냥 참아.」","mis":"K5-1-u1-X39"}],"explanation":["마음만 알아주고 멈췄어요.","시키는 말투예요.","마음 → 해 본 방법 → 권하기예요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb),
('g5_1_kor_u1_review_a#21','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C38',3,'mc','auto','「배려와 짐작은 서로를 돕는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X05']::text[],false,'{"seq":21,"concept":"K5-1-u1-C38","difficulty":3,"kind":"mc","stem":"「배려와 짐작은 서로를 돕는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"배려하니 말과 행동을 눈여겨보게 되고, 눈여겨보니 생략된 마음을 짐작할 수 있다","correct":true},{"t":"배려를 잘하면 짐작은 하지 않아도 된다","mis":"K5-1-u1-X05"},{"t":"짐작을 잘하면 배려는 하지 않아도 된다","mis":"K5-1-u1-X05"},{"t":"배려와 짐작은 서로 다른 시간에 배운다","mis":"K5-1-u1-X05"}],"explanation":["둘 다 필요해요.","둘 다 필요해요.","서로를 이끌어 줘요."]}'::jsonb),
('g5_1_kor_u1_review_a#22','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C40',3,'match','auto','문장에 알맞은 발음을 이으세요.','{}'::text[],false,'{"seq":22,"concept":"K5-1-u1-C40","difficulty":3,"kind":"match","stem":"문장에 알맞은 발음을 이으세요.","pairs":[{"l":"눈이 소복이 쌓였다","r":"눈[눈ː]"},{"l":"눈에 티가 들어갔다","r":"눈[눈]"},{"l":"벌이 꽃 위를 날아다닌다","r":"벌[벌ː]"}],"mis":"K5-1-u1-X42","explanation":["하늘에서 내리는 눈은 길어요.","몸의 눈은 짧아요.","곤충 벌은 길게 소리 내요."],"asset":{"type":"passage","lines":["눈[눈] 보는 몸의 부분　　눈[눈ː] 하늘에서 내리는 하얀 얼음 알갱이","벌[벌] 잘못한 사람에게 주는 괴로움　　벌[벌ː] 꿀을 모으는 곤충","일[일] 하나　　일[일ː] 무엇을 이루려고 몸이나 마음을 쓰는 것"],"title":"장단이 다른 낱말 더 보기"}}'::jsonb),
('g5_1_kor_u1_review_a#23','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C30',4,'mc','auto','「우산꽂이의 쪽지」에서 담우가 우산을 빌려주고도 직접 말하지 않은 까닭을 가장 알맞게 짐작한 것은 어느 것인가요?',ARRAY['K5-1-u1-X33','K5-1-u1-X28']::text[],false,'{"seq":23,"concept":"K5-1-u1-C30","difficulty":4,"kind":"mc","stem":"「우산꽂이의 쪽지」에서 담우가 우산을 빌려주고도 직접 말하지 않은 까닭을 가장 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"고마워하라고 한 일이 아니라서 드러내기 쑥스러웠을 것이다","correct":true},{"t":"해람이를 골탕 먹이려 했을 것이다","mis":"K5-1-u1-X33"},{"t":"우산을 돌려받고 싶지 않았을 것이다","mis":"K5-1-u1-X33"},{"t":"쪽지를 잘못 썼을 것이다","mis":"K5-1-u1-X28"}],"explanation":["그런 단서는 없어요.","「내일 돌려줘도 돼」라고 했어요.","머쓱한 웃음과 「들켰네」가 단서예요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb),
('g5_1_kor_u1_review_a#24','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C30',4,'essay','teacher','「우산꽂이의 쪽지」에서 생략된 내용 두 가지를 짐작해 쓰고, 각각 어떤 단서를 보고 짐작했는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u1-C30","difficulty":4,"kind":"essay","stem":"「우산꽂이의 쪽지」에서 생략된 내용 두 가지를 짐작해 쓰고, 각각 어떤 단서를 보고 짐작했는지 쓰세요.","answer_guide":{"answer":"예: 첫째, 노란 우산을 꽂아 둔 사람은 담우이다. 쪽지의 동글동글한 글씨가 담우 알림장의 글씨와 같았기 때문이다. 둘째, 담우는 우산을 빌려준 뒤 자기는 비를 맞고 집에 갔다. 다음 날 연달아 재채기를 하고 목소리가 잠겨 있었고, 「나는 집이 가까워서 괜찮아.」라고 말했기 때문이다.","scoring_points":["생략된 내용을 두 가지 짐작했는가","각 짐작의 단서를 이야기에서 찾았는가","단서와 짐작이 이어지는가"]},"explanation":["빈 곳을 찾아요.","흩어진 단서를 모아요.","단서와 짐작을 이어 써요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb),
('g5_1_kor_u1_review_a#25','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C38',4,'essay','teacher','이 단원에서 배운 「배려하며 대화하기」와 「짐작하며 대화하기」의 방법을 각각 쓰고, 두 가지가 서로 어떻게 돕는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u1-C38","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「배려하며 대화하기」와 「짐작하며 대화하기」의 방법을 각각 쓰고, 두 가지가 서로 어떻게 돕는지 쓰세요.","answer_guide":{"answer":"예: 배려하며 대화하기 — 상대의 말을 집중해서 듣기 · 상대의 기분을 고려하며 말하기 · 대화 예절 지키기 · 상황에 어울리는 표정과 행동으로 대화하기. 짐작하며 대화하기 — 말과 행동에서 단서 찾기 · 경험과 배경지식 떠올리기 · 상황 고려하기. 상대를 배려하기 때문에 말과 행동을 눈여겨보게 되고, 눈여겨보기 때문에 말하지 않은 마음을 짐작할 수 있어 두 가지는 서로를 돕는다.","scoring_points":["배려하며 대화하는 방법을 썼는가","짐작하는 방법을 썼는가","서로 돕는 관계를 썼는가"]},"explanation":["두 갈래를 떠올려요.","방법을 하나씩 써요.","서로 돕는 관계로 정리해요."]}'::jsonb),
('g5_1_kor_u1_review_b#1','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C2',1,'ox','auto','배려는 대화를 기분 좋게 이어 가게 해 주는 태도예요.',ARRAY['K5-1-u1-X02']::text[],false,'{"seq":1,"concept":"K5-1-u1-C2","difficulty":1,"kind":"ox","stem":"배려는 대화를 기분 좋게 이어 가게 해 주는 태도예요.","answer":"O","reason_options":[{"t":"서로 기분이 상하지 않아 대화가 끊기지 않기 때문에","correct":true},{"t":"배려하면 대화에서 이기기 때문에","mis":"K5-1-u1-X02"}],"mis":"K5-1-u1-X02","explanation":["맞는 말이에요.","이기고 지는 일이 아니에요.","관계를 지키는 태도예요."]}'::jsonb),
('g5_1_kor_u1_review_b#2','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C4',1,'sa','auto','짐작의 근거가 되는, 어떤 일을 풀 수 있는 실마리를 뜻하는 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K5-1-u1-C4","difficulty":1,"kind":"sa","stem":"짐작의 근거가 되는, 어떤 일을 풀 수 있는 실마리를 뜻하는 낱말을 쓰세요.","answer":["단서"],"explanation":["짐작에는 근거가 있어요.","말 · 행동 · 경험 · 상황이 그 예예요.","단서라고 해요."],"mis":"K5-1-u1-X04"}'::jsonb),
