('g5_1_kor_u1_review_d#11','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C22',2,'match','auto','찬솔이와 다래의 대화에서 단서와 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K5-1-u1-C22","difficulty":2,"kind":"match","stem":"찬솔이와 다래의 대화에서 단서와 그 갈래를 알맞게 이으세요.","pairs":[{"l":"발목을 만지작거림","r":"행동"},{"l":"「아…… 그래.」라는 짧은 대답","r":"말"},{"l":"곧 피구를 하는 체육 시간","r":"상황"}],"mis":"K5-1-u1-X25","explanation":["본 것이 행동이에요.","들은 것이 말이에요.","그때의 형편이 상황이에요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb),
