('g5_1_kor_u1_review_d#21','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C38',3,'ox','auto','상대를 배려하는 사람은 상대의 말과 행동을 눈여겨보게 되어 생략된 마음을 더 잘 짐작할 수 있어요.',ARRAY['K5-1-u1-X05']::text[],false,'{"seq":21,"concept":"K5-1-u1-C38","difficulty":3,"kind":"ox","stem":"상대를 배려하는 사람은 상대의 말과 행동을 눈여겨보게 되어 생략된 마음을 더 잘 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"배려하기 때문에 눈여겨보고, 눈여겨보기 때문에 짐작할 수 있기 때문에","correct":true},{"t":"배려하면 짐작할 일이 사라지기 때문에","mis":"K5-1-u1-X05"}],"mis":"K5-1-u1-X05","explanation":["맞는 말이에요.","짐작이 사라지지 않아요.","배려와 짐작은 서로를 도와요."]}'::jsonb),
('g5_1_kor_u1_review_d#22','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C19',3,'mc','auto','두 친구가 대화 주제를 정하는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X21','K5-1-u1-X16']::text[],false,'{"seq":22,"concept":"K5-1-u1-C19","difficulty":3,"kind":"mc","stem":"두 친구가 대화 주제를 정하는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 하고 싶은 주제를 말해 보고 둘 다 이야기하고 싶은 것으로 정한다","correct":true},{"t":"목소리가 큰 친구의 주제로 정한다","mis":"K5-1-u1-X21"},{"t":"먼저 온 친구의 주제로 정한다","mis":"K5-1-u1-X21"},{"t":"주제 없이 생각나는 대로 말한다","mis":"K5-1-u1-X16"}],"explanation":["한 사람이 빠져요.","한 사람이 빠져요.","함께 의논해 정해요."]}'::jsonb),
('g5_1_kor_u1_review_d#23','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C38',4,'mc','auto','이 단원에서 배운 것을 모두 쓴 친구의 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X08','K5-1-u1-X29','K5-1-u1-X10']::text[],false,'{"seq":23,"concept":"K5-1-u1-C38","difficulty":4,"kind":"mc","stem":"이 단원에서 배운 것을 모두 쓴 친구의 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말이 짧아진 친구 곁에서 눈을 맞추고 들으며, 행동을 단서로 마음을 짐작해 「혹시 무슨 일 있어?」라고 묻는다","correct":true},{"t":"말이 짧아진 친구에게 「왜 그렇게 짧게 말해?」라고 따진다","mis":"K5-1-u1-X08"},{"t":"친구의 마음을 짐작해 반 친구들에게 알려 준다","mis":"K5-1-u1-X29"},{"t":"친구가 말할 때 휴대 전화를 보며 「응.」이라고 한다","mis":"K5-1-u1-X10"}],"explanation":["따지는 말이에요.","짐작은 알리지 않고 확인해요.","배려하며 듣고 짐작해 물었어요."]}'::jsonb),
('g5_1_kor_u1_review_d#24','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C18',4,'essay','teacher','다래의 준비에서 빈칸을 채워 쓰고, 다래와 대화하는 친구가 할 반응하는 말을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u1-C18","difficulty":4,"kind":"essay","stem":"다래의 준비에서 빈칸을 채워 쓰고, 다래와 대화하는 친구가 할 반응하는 말을 두 가지 쓰세요.","answer_guide":{"answer":"예: 생각이나 느낌 — 손을 놓은 줄도 모르고 혼자 달리는 동생을 보니 대견하고 가슴이 뭉클했다. 반응하는 말 — 「동생이 손 놓은 걸 알았을 때 뭐라고 했어?」(이어 묻기), 「옆에서 같이 뛰어 줬으니 더 뿌듯했겠다.」(마음 알아주기)","scoring_points":["생각이나 느낌을 알맞게 채웠는가","이어 묻는 반응을 썼는가","마음을 알아주는 반응을 썼는가"]},"explanation":["그때 든 마음을 채워요.","이어받아 물어요.","마음을 알아줘요."],"asset":{"type":"passage","lines":["대화 주제 — 동생에게 처음으로 자전거 타는 법을 알려 준 일","언제 — 지난 일요일 오후에","어디에서 — 아파트 앞 공원에서","무슨 일을 — 동생 자전거 뒤를 잡고 따라 뛰다가 살며시 손을 놓았는데,","　　동생이 혼자서 공원 끝까지 달렸다.","생각이나 느낌 — ?"],"title":"다래가 준비한 내용"}}'::jsonb),
('g5_1_kor_u1_review_d#25','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C27',4,'essay','teacher','모든 대화를 짐작하며 들을 필요는 없는 까닭을 쓰고, 짐작하며 들어야 하는 때를 두 가지 이상 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u1-C27","difficulty":4,"kind":"essay","stem":"모든 대화를 짐작하며 들을 필요는 없는 까닭을 쓰고, 짐작하며 들어야 하는 때를 두 가지 이상 쓰세요.","answer_guide":{"answer":"예: 대부분의 말은 말한 그대로가 전부이고, 아무 말에나 숨은 뜻을 붙이면 오히려 오해가 생기기 때문이다. 짐작하며 들어야 하는 때는 말이 갑자기 짧아질 때, 말과 표정이 어긋날 때, 되물어야 이해될 때이다.","scoring_points":["짐작하지 않아도 되는 까닭을 썼는가","짐작이 필요한 때를 두 가지 이상 썼는가","오해와 이어 설명했는가"]},"explanation":["대부분은 말 그대로예요.","신호를 떠올려요.","오해와 이어 써요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K5-1-u2-C1','kor',5,1,'u2',1,'시간 표현의 뜻 — 시간 표현은 「지난 봄」 · 「다음 달」처럼 언제인지 알려 주는 말과 「다녀왔어」 · 「갈 거야」처럼 때를 드러내는 말끝을 함께 이르며, 곳이나 사람을 가리키는 말은 시간 표현이 아니다',ARRAY['6국04-05 문법']::text[],1),
('K5-1-u2-C2','kor',5,1,'u2',1,'때가 다르면 말끝이 달라진다 — 이미 지난 일은 「다녀왔어」, 앞으로 할 일은 「갈 거야」처럼 같은 일이라도 언제의 일인지에 따라 말끝이 달라진다',ARRAY['6국04-05 문법']::text[],2),
('K5-1-u2-C3','kor',5,1,'u2',1,'체험을 기록하면 좋은 점 — 겪은 일은 시간이 지나면 흐려지지만 글로 남기면 오래 간직하고 다른 사람에게 전할 수 있다',ARRAY['6국03-03 쓰기']::text[],3),
('K5-1-u2-C4','kor',5,1,'u2',1,'기행문의 뜻 — 기행문은 여행하며 보고, 듣고, 느끼고, 생각한 것을 쓴 글이며, 다닌 곳과 시각만 적은 일정표나 쓴 돈의 목록은 기행문이 아니다',ARRAY['6국03-03 쓰기']::text[],4),
('K5-1-u2-C5','kor',5,1,'u2',1,'체험을 떠올리는 세 물음 — 체험을 글로 쓰려면 언제 있었던 일인지, 그때 무엇을 보았는지, 무엇을 느꼈는지를 함께 떠올리며, 이 단원은 시간 표현을 활용해 글 쓰기와 기행문 쓰기의 두 갈래로 배운다',ARRAY['6국03-03 쓰기']::text[],5),
('K5-1-u2-C6','kor',5,1,'u2',2,'과거를 나타내는 말끝 — 이미 지나간 일은 「내밀었다」 · 「갔다」처럼 말끝에 -았- / -었-을 넣어 나타낸다',ARRAY['6국04-05 문법']::text[],6),
('K5-1-u2-C7','kor',5,1,'u2',2,'현재를 나타내는 말끝 — 지금 일어나고 있는 일은 「떨어진다」 · 「먹는다」처럼 말끝에 -는- / -ㄴ-을 넣어 나타낸다',ARRAY['6국04-05 문법']::text[],7),
('K5-1-u2-C8','kor',5,1,'u2',2,'미래를 나타내는 말끝 — 앞으로 일어날 일은 「내밀 것이다」 · 「가겠다」처럼 -(으)ㄹ 것이나 -겠-으로 나타낸다',ARRAY['6국04-05 문법']::text[],8),
('K5-1-u2-C9','kor',5,1,'u2',2,'말끝을 나누어 보기 — 「배웠다」를 「배우-」 · 「-었-」 · 「-다」로 나누어 보면 때를 알려 주는 부분이 「-었-」임을 알 수 있다',ARRAY['6국04-05 문법']::text[],9),
('K5-1-u2-C10','kor',5,1,'u2',2,'-는- / -ㄴ-이 늘 지금만은 아니다 — -는- / -ㄴ-은 되풀이되는 일(염소는 풀을 먹는다) · 가까운 앞일(내일 서울에 간다) · 지난 일을 생생하게 말할 때에도 쓰이며, 「하늘이 참 푸르다」처럼 이 말끝이 없어도 지금을 나타낼 수 있다',ARRAY['6국04-05 문법']::text[],10),
('K5-1-u2-C11','kor',5,1,'u2',2,'때를 나타내는 낱말 — 말끝 말고도 아까(조금 전에) · 지금 · 이제(바로 이때) · 이따 · 이따가(조금 지난 뒤에) · 곧(오래지 않아)처럼 때를 알려 주는 낱말이 있다',ARRAY['6국04-05 문법']::text[],11),
('K5-1-u2-C12','kor',5,1,'u2',2,'때를 나타내는 말과 말끝은 대개 어울린다 — 「아까 우유를 마셨다」처럼 때를 나타내는 말과 말끝이 어울려야 읽는 사람이 헷갈리지 않으며, 「아까 우유를 마실 것이다」는 어색하다',ARRAY['6국04-05 문법']::text[],12),
('K5-1-u2-C13','kor',5,1,'u2',2,'어긋나 보여도 틀린 말이 아닌 때 — 「드디어 내일 소풍 간다」 · 「지금 숙제 다 했어」처럼 겉보기에 어긋나 보여도 말끝은 때 말고도 여러 일을 하므로 틀린 말이 아니며, 소리 내어 읽어 보고 어색하지 않으면 고치지 않아도 된다',ARRAY['6국04-05 문법']::text[],13),
('K5-1-u2-C14','kor',5,1,'u2',2,'두루 쓰이는 때의 말 — 「올해」는 지금 지나가고 있는 해라서 과거 · 현재 · 미래에 모두 쓰이고, 「이듬해」는 어떤 해의 바로 다음 해라서 과거와 미래 양쪽에 쓰인다',ARRAY['6국04-05 문법']::text[],14),
('K5-1-u2-C15','kor',5,1,'u2',3,'날짜를 가리키는 우리말 — 오늘을 가운데에 두고 그끄저께(사흘 전) · 그저께(이틀 전) · 어제 · 오늘 · 내일 · 모레(이틀 뒤) · 글피(사흘 뒤)로 날짜를 가리킨다',ARRAY['6국04-05 문법']::text[],15),
('K5-1-u2-C16','kor',5,1,'u2',3,'날수를 세는 우리말 — 날의 개수는 하루 · 이틀 · 사흘 · 나흘 · 닷새 · 엿새 · 이레 · 여드레 · 아흐레 · 열흘로 센다',ARRAY['6국04-05 문법']::text[],16),
('K5-1-u2-C17','kor',5,1,'u2',3,'날짜 말과 날수 말 가르기 — 날짜를 가리키는 말은 「어느 날인지」를, 날수를 세는 말은 「며칠 동안인지」를 나타내므로 둘을 섞어 쓰면 뜻이 어긋난다',ARRAY['6국04-05 문법']::text[],17),
('K5-1-u2-C18','kor',5,1,'u2',3,'사흘은 삼 일 — 사흘은 삼 일이고 사 일은 나흘이며, 「사」라는 소리 때문에 사흘을 사 일로 잘못 아는 경우가 많다',ARRAY['6국04-05 문법']::text[],18),
('K5-1-u2-C19','kor',5,1,'u2',3,'본디부터 있던 우리말 — 이틀 · 사흘 · 나흘은 숫자에서 온 말이 아니라 본디부터 있던 우리말이므로 「2틀」 · 「3흘」처럼 숫자를 섞어 쓰면 틀린 표기가 된다',ARRAY['6국04-05 문법']::text[],19),
('K5-1-u2-C20','kor',5,1,'u2',3,'금방 · 금세 — 「금방」과 「금세」는 앞뒤 문장에 따라 조금 전(비가 금방 그쳤다) · 곧(금방 그칠 거야) · 아주 빠르게(소문이 금세 퍼졌다)처럼 가리키는 때가 달라진다',ARRAY['6국04-05 문법']::text[],20),
('K5-1-u2-C21','kor',5,1,'u2',3,'날짜 말과 날수 말로 계획 말하기 — 「모레부터 나흘 동안」처럼 언제 시작하는지는 날짜 말로, 며칠 동안인지는 날수 말로 구별해 함께 쓰면 계획이 또렷해진다',ARRAY['6국04-05 문법']::text[],21),
('K5-1-u2-C22','kor',5,1,'u2',4,'체험 글의 시간 표현과 흐름 — 있었던 일을 쓴 글에서 말끝을 보고 과거 · 현재 · 미래 표현을 찾아 나누면 「예전 → 요즘 → 다음 달」처럼 글이 시간의 차례를 따라감을 알 수 있다',ARRAY['6국04-05 문법']::text[],22),
('K5-1-u2-C23','kor',5,1,'u2',4,'때를 바꾸어 고쳐 쓰기 — 문장의 때를 바꿀 때에는 말끝과 함께 「아까 → 지금 → 이따」처럼 때를 나타내는 말도 알맞게 바꾼다',ARRAY['6국04-05 문법']::text[],23),
('K5-1-u2-C24','kor',5,1,'u2',4,'체험 글 계획의 네 항목 — 있었던 일을 쓰기 전에 누구와 언제 어떤 활동을 했는지 · 그 활동을 한 까닭 · 보고 들은 것이나 새롭게 안 것 · 생각하거나 느낀 점을 정리한다',ARRAY['6국03-03 쓰기']::text[],24),
('K5-1-u2-C25','kor',5,1,'u2',4,'체험 글의 처음 · 가운데 · 끝 — 처음에는 일을 겪은 상황이나 까닭을, 가운데에는 있었던 일을 시간의 흐름에 따라 보고 들은 것과 느낀 점을, 끝에는 전체적인 느낌과 다짐을 쓴다',ARRAY['6국03-03 쓰기']::text[],25),
('K5-1-u2-C26','kor',5,1,'u2',4,'있었던 일이 드러나는 제목 — 제목은 「토요일」처럼 막연하게 붙이지 않고 「손끝으로 고친 책들」처럼 있었던 일이 잘 드러나게 붙인다',ARRAY['6국03-03 쓰기']::text[],26),
('K5-1-u2-C27','kor',5,1,'u2',4,'기준에 따라 고쳐 쓰기 — 쓴 글은 제목 · 처음 · 가운데 · 끝의 내용 · 있었던 일의 소개 · 생각이나 느낌 · 시간 표현의 쓰임을 기준으로 스스로 확인하며 고쳐 쓴다',ARRAY['6국04-05 문법']::text[],27),
('K5-1-u2-C28','kor',5,1,'u2',4,'글을 나누고 말해 주기 — 고쳐 쓴 글을 친구들 앞에서 읽으면 듣는 사람은 시간의 흐름을 잘 따라올 수 있는지, 느낀 점이 드러나는지를 살펴 말해 준다',ARRAY['6국03-03 쓰기']::text[],28),
('K5-1-u2-C29','kor',5,1,'u2',7,'여정 — 여정은 여행하며 다닌 곳으로, 「먼저 동문으로 들어갔다」처럼 어디로 갔는지, 어디에서 어디로 옮겼는지가 드러나며 여정을 따라가면 글 전체의 흐름이 보인다',ARRAY['6국03-03 쓰기']::text[],29),
('K5-1-u2-C30','kor',5,1,'u2',7,'견문 — 견문은 여행하며 보고 들은 것으로, 눈으로 본 모습뿐 아니라 안내판에서 읽은 것과 다른 사람에게 들은 설명도 견문이다',ARRAY['6국03-03 쓰기']::text[],30),
('K5-1-u2-C31','kor',5,1,'u2',7,'감상 — 감상은 여행하며 생각하거나 느낀 것으로, 「~것 같았다」 · 「~는 생각이 들었다」처럼 마음속에서 일어난 것이 드러난다',ARRAY['6국03-03 쓰기']::text[],31),
('K5-1-u2-C32','kor',5,1,'u2',7,'견문과 감상을 가르는 물음 — 그곳에 함께 있던 다른 사람도 똑같이 확인할 수 있으면 견문, 같은 것을 보아도 사람마다 다를 수 있으면 감상이다',ARRAY['6국03-03 쓰기']::text[],32),
('K5-1-u2-C33','kor',5,1,'u2',7,'한 문단 안에서 어우러지는 세 가지 — 좋은 기행문은 「대장간에 이르렀다(여정) → 쇠를 두드리고 계셨다(견문) → 조금 알 것 같았다(감상)」처럼 셋을 따로 떼지 않고 자연스럽게 잇는다',ARRAY['6국03-03 쓰기']::text[],33),
('K5-1-u2-C34','kor',5,1,'u2',7,'일정표와 일기와 기행문 — 여정만 있으면 일정표가 되고 감상만 있으면 일기에 가까워지며, 여정 · 견문 · 감상이 함께 있어야 기행문이다',ARRAY['6국03-03 쓰기']::text[],34),
('K5-1-u2-C35','kor',5,1,'u2',7,'가까운 곳도 기행문의 글감 — 먼 곳이나 이름난 곳에 다녀온 여행뿐 아니라 우리 동네 골목 · 현장 체험 학습 · 명절에 간 친척 집 · 가까운 시장이나 박물관도 다닌 곳과 보고 느낀 것이 있으면 기행문의 글감이다',ARRAY['6국03-03 쓰기']::text[],35),
('K5-1-u2-C36','kor',5,1,'u2',7,'기행문의 두 몫과 여러 형식 — 기행문은 그때의 느낌을 오래 새겨 두는 몫과 가 보지 않은 사람에게 그곳의 정보를 전하는 몫을 함께 지니며, 글과 사진뿐 아니라 그림 · 엽서 · 편지 · 동영상으로도 남길 수 있다',ARRAY['6국03-03 쓰기']::text[],36),
('K5-1-u2-C37','kor',5,1,'u2',9,'기행문의 처음 — 처음에는 여행지 이름 · 함께 간 사람 · 교통편 · 떠난 까닭과 기대 · 출발할 때의 날씨와 기분을 쓴다',ARRAY['6국03-03 쓰기']::text[],37),
('K5-1-u2-C38','kor',5,1,'u2',9,'기행문의 가운데 — 가운데에는 공간의 이동이나 시간의 흐름에 따라 다닌 곳마다 견문과 감상을 함께 쓴다',ARRAY['6국03-03 쓰기']::text[],38),
('K5-1-u2-C39','kor',5,1,'u2',9,'기행문의 끝 — 끝에는 여행하고 난 뒤의 전체적인 느낌 · 배운 것이나 더 알고 싶은 것 · 앞으로의 계획이나 각오를 쓴다',ARRAY['6국03-03 쓰기']::text[],39),
('K5-1-u2-C40','kor',5,1,'u2',9,'기행문의 제목 — 기행문의 제목은 여행지와 느낌이 함께 드러나게 붙인다',ARRAY['6국03-03 쓰기']::text[],40),
('K5-1-u2-C41','kor',5,1,'u2',9,'개요 짜기 — 기행문을 쓰기 전에 여행 사진이나 일기를 보며 기억에 남는 장면을 떠올리고, 쓸 여행 경험 하나를 골라 처음 · 가운데 · 끝에 들어갈 내용을 개요로 정리하며, 가운데는 다닌 곳별로 견문과 감상을 나란히 적는다',ARRAY['6국03-03 쓰기']::text[],41),
('K5-1-u2-C42','kor',5,1,'u2',9,'쓰기 과정 점검하기 — 계획하기 · 글쓰기 · 수정하기 가운데 아쉬웠던 단계를 짚어 보완할 점과 수정할 방법을 적어 두면 다음 글이 나아진다(여정 · 견문 · 감상을 한 문단씩 따로 썼다면 다닌 곳마다 어우러지게 다시 묶는다)',ARRAY['6국03-03 쓰기']::text[],42),
('K5-1-u2-C43','kor',5,1,'u2',12,'안내장에 들어갈 내용 — 여행지 안내장에는 그곳에 가려는 사람이 궁금해할 갈 만한 곳 · 먹을거리 · 즐길 거리 · 문화유산을 담는다',ARRAY['6국03-03 쓰기']::text[],43),
('K5-1-u2-C44','kor',5,1,'u2',12,'안내장의 형태와 쓰임 — 관광 지도는 다닌 곳의 위치와 차례를, 그림엽서는 한 장면과 짧은 글로 인상을, 소책자는 여러 쪽에 자세한 설명을, 광고지는 한 면에 눈에 띄게 정리한 내용을 전한다',ARRAY['6국03-03 쓰기']::text[],44),
('K5-1-u2-C45','kor',5,1,'u2',12,'공공 누리집 자료를 쓰는 태도 — 공공 누리집의 사진과 설명 자료는 쓸 수 있는 범위가 정해져 있으므로 이용 조건을 확인하고 출처를 밝혀 쓴다',ARRAY['6국03-03 쓰기']::text[],45),
('K5-1-u2-C46','kor',5,1,'u2',12,'안내장에도 감상을 담는다 — 정보만 있으면 안내판이 되고 글쓴이의 느낌이 있어야 가 보고 싶어지므로, 안내장의 항목마다 내가 느낀 한 문장을 넣는다',ARRAY['6국03-03 쓰기']::text[],46),
('K5-1-u2-C47','kor',5,1,'u2',12,'실천 활동은 반에서 함께 정한다 — 배운 것을 실천하는 활동은 안내장 하나로 정해져 있지 않고, 시간 여행으로 이야기 꾸미기 · 최고의 여행지 소개하기처럼 반에서 함께 정할 수 있다',ARRAY['6국03-03 쓰기']::text[],47),
('K5-1-u2-C48','kor',5,1,'u2',12,'안내장 발표와 듣기 — 발표할 때에는 왜 이곳을 골랐는지부터 말하고, 듣는 사람은 가 보고 싶어졌는지와 어느 문구에서 그런 마음이 들었는지를 말해 준다',ARRAY['6국03-03 쓰기']::text[],48),
('K5-1-u2-C49','kor',5,1,'u2',12,'두 소단원은 이어져 있다 — 기행문은 시간과 공간을 따라 움직이는 글이라 시간 표현이 흔들리면 다닌 길도 흐트러지므로, 시간 표현이 기행문의 뼈대를 세운다',ARRAY['6국03-03 쓰기']::text[],49),
('K5-1-u2-C50','kor',5,1,'u2',12,'「이」로 끝나는 낱말 — 깨끗이 · 틈틈이 · 곰곰이 · 일일이 · 샅샅이 · 가까이처럼 「이」로 끝나는 낱말은 소리만으로 가리기 어려우므로 눈으로 익혀 둔다 (기초 다지기)',ARRAY['기초 다지기(이·히)']::text[],50),
('K5-1-u2-C51','kor',5,1,'u2',12,'「히」로 끝나는 낱말 — 다행히 · 조용히 · 특별히 · 도저히 · 분명히 · 솔직히처럼 「히」로 끝나는 낱말을 문장 속에서 바르게 쓴다 (기초 다지기)',ARRAY['기초 다지기(이·히)']::text[],51)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K5-1-u2-X01','kor',5,'u2',ARRAY['K5-1-u2-C1']::text[],'「산책로」 · 「숲길」처럼 곳을 가리키는 말까지 시간 표현으로 고른다','언제인지 알려 주나?'),
('K5-1-u2-X02','kor',5,'u2',ARRAY['K5-1-u2-C2']::text[],'말끝이 달라진 까닭을 간 곳이나 말한 사람이 달라서라고 여긴다','지난 일 · 앞으로 할 일'),
('K5-1-u2-X03','kor',5,'u2',ARRAY['K5-1-u2-C3']::text[],'겪은 일은 적어 두지 않아도 오래 또렷하게 기억된다고 여긴다','기억은 흐려져요'),
('K5-1-u2-X04','kor',5,'u2',ARRAY['K5-1-u2-C4']::text[],'다닌 곳과 시각만 적은 일정표나 쓴 돈의 목록도 기행문이라고 여긴다','보고 느낀 것이 있나?'),
('K5-1-u2-X05','kor',5,'u2',ARRAY['K5-1-u2-C6','K5-1-u2-C7','K5-1-u2-C8']::text[],'과거 · 현재 · 미래를 나타내는 말끝을 서로 바꾸어 안다','-었- · -ㄴ- · -ㄹ 것'),
('K5-1-u2-X06','kor',5,'u2',ARRAY['K5-1-u2-C9']::text[],'말끝에서 때를 알려 주는 부분을 낱말의 뿌리나 「-다」로 잘못 짚는다','나누어 보세요'),
('K5-1-u2-X07','kor',5,'u2',ARRAY['K5-1-u2-C10']::text[],'-는- / -ㄴ-은 언제나 바로 지금 일어나는 일만 뜻한다고 여긴다','되풀이 · 가까운 앞일도'),
('K5-1-u2-X08','kor',5,'u2',ARRAY['K5-1-u2-C10']::text[],'-는- / -ㄴ-이 붙지 않으면 지금을 나타내는 문장이 아니라고 여긴다','「하늘이 참 푸르다」'),
('K5-1-u2-X09','kor',5,'u2',ARRAY['K5-1-u2-C11']::text[],'「아까」와 「이따」처럼 때를 나타내는 낱말의 앞뒤를 거꾸로 안다','조금 전 · 조금 뒤'),
('K5-1-u2-X10','kor',5,'u2',ARRAY['K5-1-u2-C12']::text[],'「아까 … 마실 것이다」처럼 때를 나타내는 말과 말끝이 어색하게 어울려도 그대로 둔다','소리 내어 읽어 봐요'),
('K5-1-u2-X11','kor',5,'u2',ARRAY['K5-1-u2-C13']::text[],'「드디어 내일 소풍 간다」처럼 겉보기에 어긋나 보이는 문장을 모두 틀렸다고 여겨 고친다','어색하지 않으면 그대로'),
('K5-1-u2-X12','kor',5,'u2',ARRAY['K5-1-u2-C14']::text[],'「올해」나 「이듬해」를 한 가지 때에만 쓰는 말로 여긴다','두루 쓰여요'),
('K5-1-u2-X13','kor',5,'u2',ARRAY['K5-1-u2-C15']::text[],'그저께 · 모레 · 글피가 오늘에서 며칠 앞뒤인지 헷갈린다','오늘을 가운데에'),
('K5-1-u2-X14','kor',5,'u2',ARRAY['K5-1-u2-C16']::text[],'닷새 · 엿새 · 이레처럼 날수를 세는 말의 차례를 헷갈린다','하루부터 차례로'),
('K5-1-u2-X15','kor',5,'u2',ARRAY['K5-1-u2-C17']::text[],'「모레 동안」 · 「이틀에 간다」처럼 날짜 말과 날수 말을 섞어 쓴다','어느 날 · 며칠 동안'),
('K5-1-u2-X16','kor',5,'u2',ARRAY['K5-1-u2-C18']::text[],'「사」라는 소리 때문에 사흘을 사 일로 안다','사흘은 삼 일'),
('K5-1-u2-X17','kor',5,'u2',ARRAY['K5-1-u2-C19']::text[],'이틀 · 사흘을 「2틀」 · 「3흘」처럼 숫자를 섞어 쓴다','본디부터 있던 우리말'),
('K5-1-u2-X18','kor',5,'u2',ARRAY['K5-1-u2-C20']::text[],'「금방」 · 「금세」가 늘 한 가지 때만 가리킨다고 여긴다','앞뒤 문장을 봐요'),
('K5-1-u2-X19','kor',5,'u2',ARRAY['K5-1-u2-C21']::text[],'계획을 말할 때 언제 시작하는지와 며칠 동안인지를 구별하지 않아 흐릿하게 말한다','날짜 말 + 날수 말'),
('K5-1-u2-X20','kor',5,'u2',ARRAY['K5-1-u2-C22']::text[],'글에서 시간 표현을 찾을 때 말끝을 보지 않아 「예전 → 요즘 → 다음 달」의 흐름을 놓친다','말끝이 때를 알려 줘요'),
('K5-1-u2-X21','kor',5,'u2',ARRAY['K5-1-u2-C23']::text[],'때를 바꿀 때 말끝만 바꾸고 「아까」 같은 때를 나타내는 말은 그대로 두어 어색하게 만든다','때의 말도 함께'),
('K5-1-u2-X22','kor',5,'u2',ARRAY['K5-1-u2-C24']::text[],'계획의 네 항목 가운데 활동을 한 까닭이나 느낀 점을 빠뜨린다','네 항목과 맞추어 봐요'),
('K5-1-u2-X23','kor',5,'u2',ARRAY['K5-1-u2-C25']::text[],'다짐을 처음에 쓰거나 일을 겪은 까닭을 끝에 쓰는 것처럼 처음 · 가운데 · 끝의 내용을 뒤섞는다','상황 → 있었던 일 → 느낌과 다짐'),
('K5-1-u2-X24','kor',5,'u2',ARRAY['K5-1-u2-C25']::text[],'가운데 부분을 시간의 흐름과 상관없이 생각나는 대로 늘어놓는다','시간의 흐름에 따라'),
('K5-1-u2-X25','kor',5,'u2',ARRAY['K5-1-u2-C26']::text[],'「토요일」 · 「나의 하루」처럼 있었던 일이 드러나지 않는 제목을 붙인다','무슨 일이었나?'),
('K5-1-u2-X26','kor',5,'u2',ARRAY['K5-1-u2-C27']::text[],'고쳐 쓰기를 맞춤법만 살피는 일로 여겨 짜임 · 느낌 · 시간 표현은 확인하지 않는다','기준이 여럿이에요'),
('K5-1-u2-X27','kor',5,'u2',ARRAY['K5-1-u2-C28']::text[],'친구의 글을 듣고 흐름이나 느낌이 아니라 글의 길이나 글씨만 말해 준다','흐름과 느낌을 살펴요'),
('K5-1-u2-X28','kor',5,'u2',ARRAY['K5-1-u2-C29']::text[],'다닌 곳을 밝힌 문장과 보거나 느낀 것을 쓴 문장을 헷갈린다','어디로 갔나?'),
('K5-1-u2-X29','kor',5,'u2',ARRAY['K5-1-u2-C30']::text[],'안내판에서 읽거나 다른 사람에게 들은 설명은 견문이 아니라고 여긴다','들은 것도 견문'),
('K5-1-u2-X30','kor',5,'u2',ARRAY['K5-1-u2-C31']::text[],'마음속에서 일어난 생각을 보고 들은 사실로 여긴다','마음이 드러났나?'),
('K5-1-u2-X31','kor',5,'u2',ARRAY['K5-1-u2-C32']::text[],'견문과 감상을 문장의 길이나 꾸미는 말이 많고 적음으로 가른다','누구나 똑같이 확인할 수 있나?'),
('K5-1-u2-X32','kor',5,'u2',ARRAY['K5-1-u2-C33','K5-1-u2-C42']::text[],'여정 · 견문 · 감상을 한 문단씩 따로 떼어 써야 한다고 여긴다','다닌 곳마다 어우러지게'),
('K5-1-u2-X33','kor',5,'u2',ARRAY['K5-1-u2-C34']::text[],'다닌 곳만 늘어놓거나 느낌만 써도 기행문이 된다고 여긴다','셋이 함께'),
('K5-1-u2-X34','kor',5,'u2',ARRAY['K5-1-u2-C35']::text[],'멀리 떠난 이름난 여행만 기행문의 글감이 된다고 여긴다','가까운 곳도 글감'),
('K5-1-u2-X35','kor',5,'u2',ARRAY['K5-1-u2-C36']::text[],'기행문은 느낌만 담는 글이고 글로만 남길 수 있다고 여긴다','두 몫 · 여러 형식'),
('K5-1-u2-X36','kor',5,'u2',ARRAY['K5-1-u2-C37']::text[],'떠난 까닭 · 기대 · 출발할 때의 날씨를 처음에 쓰지 않거나 끝으로 미룬다','떠나기 전과 막 도착했을 때'),
('K5-1-u2-X37','kor',5,'u2',ARRAY['K5-1-u2-C38']::text[],'가운데 부분에서 다닌 차례를 뒤섞거나 다닌 곳만 쓰고 견문과 감상을 빠뜨린다','다닌 곳마다 차례대로'),
('K5-1-u2-X38','kor',5,'u2',ARRAY['K5-1-u2-C39']::text[],'끝부분에 새로 다닌 곳을 이어 쓰고 전체적인 느낌이나 앞으로의 계획은 빠뜨린다','돌아본 느낌과 계획'),
('K5-1-u2-X39','kor',5,'u2',ARRAY['K5-1-u2-C40']::text[],'제목에 여행지만 쓰거나 느낌만 써서 어떤 여행인지 짐작하기 어렵게 한다','여행지 + 느낌'),
('K5-1-u2-X40','kor',5,'u2',ARRAY['K5-1-u2-C41']::text[],'개요 없이 바로 쓰거나 여러 여행을 한 글에 섞어 쓴다','경험 하나 · 개요 먼저'),
('K5-1-u2-X41','kor',5,'u2',ARRAY['K5-1-u2-C42']::text[],'다 쓰면 끝이라고 여겨 쓰기 과정의 어느 단계가 아쉬웠는지 돌아보지 않는다','계획 · 쓰기 · 수정'),
('K5-1-u2-X42','kor',5,'u2',ARRAY['K5-1-u2-C43']::text[],'안내장에 우리 집 주소나 내 시험 점수처럼 여행지와 관계없는 내용을 넣는다','가려는 사람이 궁금한 것'),
('K5-1-u2-X43','kor',5,'u2',ARRAY['K5-1-u2-C44']::text[],'전할 내용의 양과 방식에 맞지 않는 안내장 형태를 고른다','지도 · 엽서 · 소책자 · 광고지'),
('K5-1-u2-X44','kor',5,'u2',ARRAY['K5-1-u2-C45']::text[],'누리집에 공개된 자료는 이용 조건을 보지 않고 출처 없이 가져다 써도 된다고 여긴다','조건 확인 · 출처 밝히기'),
('K5-1-u2-X45','kor',5,'u2',ARRAY['K5-1-u2-C46']::text[],'안내장에는 관람 시간 같은 사실 정보만 넣고 감상은 넣지 않아도 된다고 여긴다','느낌이 마음을 옮겨요'),
('K5-1-u2-X46','kor',5,'u2',ARRAY['K5-1-u2-C47']::text[],'배운 것을 실천하는 활동은 안내장 만들기 하나뿐이라고 여긴다','반에서 함께 정해요'),
('K5-1-u2-X47','kor',5,'u2',ARRAY['K5-1-u2-C48']::text[],'발표할 때 고른 까닭은 빼고 정보만 읽거나, 듣고 나서 어느 문구가 좋았는지 짚지 않는다','까닭부터 · 문구 짚기'),
('K5-1-u2-X48','kor',5,'u2',ARRAY['K5-1-u2-C49']::text[],'시간 표현 공부와 기행문 쓰기를 서로 관계없는 따로 떨어진 공부로 여긴다','시간 표현이 뼈대'),
('K5-1-u2-X49','kor',5,'u2',ARRAY['K5-1-u2-C50']::text[],'「깨끗이」 · 「틈틈이」 · 「곰곰이」를 「히」로 잘못 쓴다','「이」로 끝나는 무리'),
('K5-1-u2-X50','kor',5,'u2',ARRAY['K5-1-u2-C51']::text[],'「조용히」 · 「솔직히」 · 「분명히」를 「이」로 잘못 쓴다','「히」로 끝나는 무리')
